-- WEB-UIUX-001/19 S1 OFFLINE CANDIDATE. One atomic DO, no guards disabled.
-- JSON escaped source keeps the installed body bytes independent of SQL Editor CRLF.
DO $line_voice$
DECLARE payload jsonb := '{"patches":[{"identity":"public.record_signature_voice_source_access(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_asset_id uuid, p_admin_customer_id uuid, p_access_mode text, p_range_requested boolean)","before":{"oid":"91297","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":77,"identity":"public.record_signature_voice_source_access(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_asset_id uuid, p_admin_customer_id uuid, p_access_mode text, p_range_requested boolean)","in_scope":true,"language":"plpgsql","lf_count":77,"body_bytes":2260,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"d7cb806f234613aa5ed1198bcd54bc01","definition_md5":"7418da9f07ae17b922243f9be0b69376","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_asset public.user_assets%rowtype;\nbegin\n  if p_access_mode not in (''playback'', ''download'') then\n    raise exception ''signature_voice_access_mode_invalid'' using errcode = ''22023'';\n  end if;\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''admin_access_required'' using errcode = ''42501'';\n  end if;\n\n  select asset.*\n  into v_asset\n  from public.orders purchase_order\n  join public.cart_items item\n    on item.order_id = purchase_order.order_id\n  join public.order_line_voice creation\n    on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  join public.user_assets asset\n    on asset.asset_id = creation.voice_asset_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n    and creation.creation_id = p_creation_id\n    and creation.voice_asset_id = p_asset_id\n    and asset.asset_type::text = ''voice_sample'';\n\n  if not found then\n    raise exception ''signature_voice_source_not_found'' using errcode = ''P0002'';\n  end if;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    metadata\n  )\n  values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_asset_id,\n    p_admin_customer_id,\n    ''source_accessed'',\n    jsonb_build_object(\n      ''access_mode'', p_access_mode,\n      ''range_requested'', coalesce(p_range_requested, false)\n    )\n  );\n\n  return query\n  select\n    v_asset.asset_id,\n    ''raw-private''::text,\n    v_asset.storage_path,\n    nullif(v_asset.metadata ->> ''content_type'', ''''),\n    case\n      when (v_asset.metadata ->> ''size_bytes'') ~ ''^[0-9]+$''\n        then (v_asset.metadata ->> ''size_bytes'')::bigint\n      else null\n    end,\n    case\n      when (v_asset.metadata ->> ''duration_seconds'') ~ ''^[0-9]+([.][0-9]+)?$''\n        then (v_asset.metadata ->> ''duration_seconds'')::numeric\n      else null\n    end;\nend;\n","after_md5":"56193325a8a2c11f5f9e95f02d9626cb"},{"identity":"public.record_signature_voice_narration_access(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_slot_key text, p_source_asset_id uuid, p_track_asset_id uuid, p_admin_customer_id uuid, p_access_mode text, p_range_requested boolean)","before":{"oid":"91389","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":78,"identity":"public.record_signature_voice_narration_access(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_slot_key text, p_source_asset_id uuid, p_track_asset_id uuid, p_admin_customer_id uuid, p_access_mode text, p_range_requested boolean)","in_scope":true,"language":"plpgsql","lf_count":78,"body_bytes":2344,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"ee4bd10664540eb76e9d67ffa0e5b258","definition_md5":"265445d3b5a45680ee2d27b4c975566e","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_track public.signature_voice_narration_tracks%rowtype;\nbegin\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''admin_access_required'' using errcode = ''42501'';\n  end if;\n  if p_access_mode is null\n    or p_access_mode not in (''playback'', ''download'')\n    or p_slot_key is null\n    or p_slot_key !~ ''^narration_(0[1-9]|1[0-5])$'' then\n    raise exception ''signature_voice_narration_access_invalid'' using errcode = ''22023'';\n  end if;\n\n  select track.*\n  into v_track\n  from public.orders purchase_order\n  join public.cart_items item\n    on item.order_id = purchase_order.order_id\n  join public.order_line_voice creation\n    on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  join public.signature_voice_narration_tracks track\n    on track.creation_id = creation.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n    and creation.creation_id = p_creation_id\n    and creation.voice_asset_id = p_source_asset_id\n    and track.slot_key = p_slot_key\n    and track.source_asset_id = p_source_asset_id\n    and track.asset_id = p_track_asset_id;\n\n  if not found then\n    raise exception ''signature_voice_narration_not_found'' using errcode = ''P0002'';\n  end if;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    metadata\n  )\n  values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_track_asset_id,\n    p_admin_customer_id,\n    ''narration_accessed'',\n    jsonb_build_object(\n      ''slot_key'', p_slot_key,\n      ''voice_source_asset_id'', p_source_asset_id,\n      ''access_mode'', p_access_mode,\n      ''range_requested'', coalesce(p_range_requested, false)\n    )\n  );\n\n  return query\n  select\n    v_track.asset_id,\n    ''raw-private''::text,\n    v_track.storage_path,\n    v_track.original_filename,\n    v_track.content_type,\n    v_track.size_bytes,\n    v_track.duration_seconds,\n    v_track.sha256;\nend;\n","after_md5":"df733fad47c7dea98da56c43e5c5e0eb"},{"identity":"public.mark_signature_voice_shipment_integrity(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_source_asset_id uuid, p_expected_manifest_sha256 text, p_admin_customer_id uuid)","before":{"oid":"91460","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":101,"identity":"public.mark_signature_voice_shipment_integrity(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_source_asset_id uuid, p_expected_manifest_sha256 text, p_admin_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":101,"body_bytes":3865,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"8473a4530ae4d9907d3758ea48e11908","definition_md5":"73310343a55da8bb7ec615b20e871e84","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_source_asset_id uuid;\n  v_state public.signature_voice_production_states%rowtype;\n  v_attestation public.signature_voice_hardware_attestations%rowtype;\n  v_track_count integer;\n  v_manifest_sha256 text;\n  v_now timestamptz := now();\nbegin\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''Admin actor is required'' using errcode = ''42501'';\n  end if;\n  if p_expected_manifest_sha256 !~ ''^[0-9a-f]{64}$'' then\n    raise exception ''Signature Voice narration manifest is invalid'' using errcode = ''22023'';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text, 0));\n\n  select creation.voice_asset_id\n  into v_source_asset_id\n  from public.cart_items item\n  join public.orders purchase_order on purchase_order.order_id = item.order_id\n  join public.order_line_voice creation on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.creation_id = p_creation_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n  for update of creation;\n\n  if not found or v_source_asset_id is null then\n    raise exception ''Paid Signature Voice order item was not found'' using errcode = ''P0002'';\n  end if;\n  if v_source_asset_id is distinct from p_source_asset_id then\n    raise exception ''Signature Voice source changed before shipment verification'' using errcode = ''PT409'';\n  end if;\n\n  select state.* into v_state\n  from public.signature_voice_production_states state\n  where state.cart_item_id = p_cart_item_id;\n  if not found\n    or v_state.technical_status <> ''accepted''\n    or v_state.adult_declaration_status <> ''accepted'' then\n    raise exception ''Signature Voice source triage is not accepted'' using errcode = ''55000'';\n  end if;\n\n  select manifest.out_track_count, manifest.out_manifest_sha256\n  into v_track_count, v_manifest_sha256\n  from public.signature_voice_narration_manifest(p_cart_item_id, p_source_asset_id) manifest;\n  if v_track_count <> 15 or v_manifest_sha256 is null then\n    raise exception ''All 15 Signature Voice narration tracks are required before shipment''\n      using errcode = ''55000'';\n  end if;\n  if v_manifest_sha256 is distinct from p_expected_manifest_sha256 then\n    raise exception ''Signature Voice narration changed during shipment verification''\n      using errcode = ''PT409'';\n  end if;\n\n  select attestation.* into v_attestation\n  from public.signature_voice_hardware_attestations attestation\n  where attestation.cart_item_id = p_cart_item_id\n  for update;\n  if not found\n    or v_attestation.source_asset_id is distinct from p_source_asset_id\n    or v_attestation.narration_manifest_sha256 is distinct from v_manifest_sha256 then\n    raise exception ''Signature Voice hardware loading must be confirmed before shipment''\n      using errcode = ''55000'';\n  end if;\n\n  update public.signature_voice_hardware_attestations attestation\n  set shipment_integrity_checked_by = p_admin_customer_id,\n      shipment_integrity_checked_at = v_now,\n      updated_at = v_now\n  where attestation.cart_item_id = p_cart_item_id;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    metadata\n  ) values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_source_asset_id,\n    p_admin_customer_id,\n    ''shipment_integrity_verified'',\n    jsonb_build_object(''manifest_sha256'', v_manifest_sha256, ''track_count'', v_track_count)\n  );\n\n  return query select p_creation_id, v_now;\nend;\n","after_md5":"bfdf82070c61e6a1684365370a9c3a77"},{"identity":"public.attest_signature_voice_hardware_loaded(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_source_asset_id uuid, p_expected_manifest_sha256 text, p_admin_customer_id uuid)","before":{"oid":"91459","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":115,"identity":"public.attest_signature_voice_hardware_loaded(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_source_asset_id uuid, p_expected_manifest_sha256 text, p_admin_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":115,"body_bytes":3954,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"eb7e82cf5864c253830b11843b10049b","definition_md5":"137fd06fdf81357532ab98e308b0398a","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_source_asset_id uuid;\n  v_state public.signature_voice_production_states%rowtype;\n  v_track_count integer;\n  v_manifest_sha256 text;\n  v_now timestamptz := now();\nbegin\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''Admin actor is required'' using errcode = ''42501'';\n  end if;\n  if p_expected_manifest_sha256 !~ ''^[0-9a-f]{64}$'' then\n    raise exception ''Signature Voice narration manifest is invalid'' using errcode = ''22023'';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text, 0));\n\n  select creation.voice_asset_id\n  into v_source_asset_id\n  from public.cart_items item\n  join public.orders purchase_order on purchase_order.order_id = item.order_id\n  join public.order_line_voice creation on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.creation_id = p_creation_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n  for update of creation;\n\n  if not found or v_source_asset_id is null then\n    raise exception ''Paid Signature Voice order item was not found'' using errcode = ''P0002'';\n  end if;\n  if v_source_asset_id is distinct from p_source_asset_id then\n    raise exception ''Signature Voice source changed before hardware confirmation'' using errcode = ''PT409'';\n  end if;\n\n  select state.* into v_state\n  from public.signature_voice_production_states state\n  where state.cart_item_id = p_cart_item_id\n  for update;\n  if not found\n    or v_state.technical_status <> ''accepted''\n    or v_state.adult_declaration_status <> ''accepted'' then\n    raise exception ''Signature Voice source triage must be accepted before hardware loading''\n      using errcode = ''55000'';\n  end if;\n\n  select manifest.out_track_count, manifest.out_manifest_sha256\n  into v_track_count, v_manifest_sha256\n  from public.signature_voice_narration_manifest(p_cart_item_id, p_source_asset_id) manifest;\n  if v_track_count <> 15 or v_manifest_sha256 is null then\n    raise exception ''All 15 Signature Voice narration tracks are required before hardware loading''\n      using errcode = ''55000'';\n  end if;\n  if v_manifest_sha256 is distinct from p_expected_manifest_sha256 then\n    raise exception ''Signature Voice narration changed during hardware verification''\n      using errcode = ''PT409'';\n  end if;\n\n  insert into public.signature_voice_hardware_attestations (\n    cart_item_id, creation_id,\n    source_asset_id,\n    narration_manifest_sha256,\n    attested_by,\n    attested_at,\n    shipment_integrity_checked_by,\n    shipment_integrity_checked_at,\n    created_at,\n    updated_at\n  ) values (\n    p_cart_item_id, p_creation_id,\n    p_source_asset_id,\n    v_manifest_sha256,\n    p_admin_customer_id,\n    v_now,\n    null,\n    null,\n    v_now,\n    v_now\n  )\n  on conflict (cart_item_id) do update\n  set source_asset_id = excluded.source_asset_id,\n      narration_manifest_sha256 = excluded.narration_manifest_sha256,\n      attested_by = excluded.attested_by,\n      attested_at = excluded.attested_at,\n      shipment_integrity_checked_by = null,\n      shipment_integrity_checked_at = null,\n      updated_at = excluded.updated_at;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    metadata\n  ) values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_source_asset_id,\n    p_admin_customer_id,\n    ''hardware_loaded_attested'',\n    jsonb_build_object(''manifest_sha256'', v_manifest_sha256, ''track_count'', v_track_count)\n  );\n\n  return query select p_creation_id, v_manifest_sha256, v_now;\nend;\n","after_md5":"679010643fb24704a41c912747260b84"},{"identity":"public.materials_initialize_order_lines(p_order uuid)","before":{"oid":"95102","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres}","cr_count":13,"identity":"public.materials_initialize_order_lines(p_order uuid)","in_scope":false,"language":"plpgsql","lf_count":13,"body_bytes":771,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"void","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"43744791312aab04d6c384485de4a92d","definition_md5":"c7461f17be3c5d301eaac19b535aa6e1","security_definer":true,"execute_privileges":{"anon":false,"service_role":false,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":false},"body":"\nDECLARE o public.orders%rowtype;\nBEGIN\n  SELECT * INTO o FROM public.orders WHERE order_id=p_order FOR UPDATE;\n  PERFORM public.initialize_order_line_voice(p_order);\n  IF o.paid_at IS NULL OR o.payment_id IS NULL\n    OR o.order_status::text NOT IN (''paid'',''production'') THEN RETURN; END IF;\n  INSERT INTO public.cart_item_dedications\n    (cart_item_id,order_id,creation_id,decision,body,source_revision,revision)\n  SELECT i.cart_item_id,i.order_id,i.creation_id,coalesce(d.decision,''skipped''),d.body,\n    coalesce(d.revision,1),1\n  FROM public.cart_items i LEFT JOIN public.creation_dedications d ON d.creation_id=i.creation_id\n  WHERE i.order_id=p_order AND i.status::text=''ordered''\n    AND NOT EXISTS (SELECT 1 FROM public.cart_item_dedications saved WHERE saved.cart_item_id=i.cart_item_id);\nEND ","after_md5":"8fcc5c10e1be2808a73ef76ef4b8a8f3"},{"identity":"public.materials_initialize_paid_lines()","before":{"oid":"95103","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres}","cr_count":6,"identity":"public.materials_initialize_paid_lines()","in_scope":false,"language":"plpgsql","lf_count":6,"body_bytes":166,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"d97ce56518ea0a32f2d98f9ea127eed5","definition_md5":"5af92b35c341b7f140b06e23e4583363","security_definer":true,"execute_privileges":{"anon":false,"service_role":false,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":false},"body":"\nBEGIN\n  IF NEW.paid_at IS NOT NULL AND NEW.payment_id IS NOT NULL THEN\n    PERFORM public.materials_initialize_order_lines(NEW.order_id);\n  END IF;\n  RETURN NEW;\nEND ","after_md5":"48d4e68686e84687bb63521bcbb23210"},{"identity":"public.materials_read(p_order uuid, p_customer uuid, p_hash text)","before":{"oid":"95108","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":23,"identity":"public.materials_read(p_order uuid, p_customer uuid, p_hash text)","in_scope":true,"language":"plpgsql","lf_count":23,"body_bytes":1556,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"jsonb","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"39d15c9b8da45673469de45a725ed967","definition_md5":"87bda8784fa2db5f284983a97a7f7762","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\nDECLARE result jsonb;\nBEGIN\n  PERFORM public.materials_assert_access(p_order,p_customer,p_hash);\n  IF EXISTS(SELECT 1 FROM public.cart_items i LEFT JOIN public.cart_item_dedications d\n    ON d.cart_item_id=i.cart_item_id WHERE i.order_id=p_order AND i.status::text=''ordered''\n      AND d.cart_item_id IS NULL) THEN RAISE EXCEPTION ''materials_lines_unavailable''; END IF;\n  IF EXISTS(SELECT 1 FROM public.cart_items i LEFT JOIN public.order_line_voice v ON v.cart_item_id=i.cart_item_id\n    WHERE i.order_id=p_order AND i.status::text=''ordered'' AND i.package_type::text=''supreme'' AND v.cart_item_id IS NULL)\n    THEN RAISE EXCEPTION ''materials_lines_unavailable''; END IF;\n  SELECT jsonb_build_object(''order_id'',o.order_id,''dedication_deadline'',o.paid_at+interval ''48 hours'',\n    ''items'',coalesce(jsonb_agg(jsonb_build_object(''cart_item_id'',i.cart_item_id,\n      ''creation_id'',i.creation_id,''template_id'',c.template_id,''package_type'',i.package_type,\n      ''dedication'',jsonb_build_object(''body'',d.body,''decision'',d.decision,''revision'',d.revision),\n      ''can_edit_dedication'',clock_timestamp()<o.paid_at+interval ''48 hours'',\n      ''voice_ready'',v.voice_asset_id IS NOT NULL,\n      ''can_submit_voice'',i.package_type=''supreme'' AND v.voice_asset_id IS NULL)\n      ORDER BY i.cart_item_id),''[]''::jsonb)) INTO result\n  FROM public.orders o JOIN public.cart_items i ON i.order_id=o.order_id AND i.status::text=''ordered''\n  JOIN public.creations c ON c.creation_id=i.creation_id\n  JOIN public.cart_item_dedications d ON d.cart_item_id=i.cart_item_id\n  LEFT JOIN public.order_line_voice v ON v.cart_item_id=i.cart_item_id\n  WHERE o.order_id=p_order AND (p_hash IS NULL OR i.cart_item_id=ANY(\n    (SELECT item_ids FROM public.order_material_grants WHERE token_hash=p_hash)::uuid[]))\n  GROUP BY o.order_id,o.paid_at;\n  IF result IS NULL THEN RAISE EXCEPTION ''materials_lines_unavailable''; END IF;\n  RETURN result;\nEND ","after_md5":"c246f44ffe7828e1017afdd005e15d83"},{"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","before":{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"37f9def7c2883031342142c6860d904b","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_asset public.user_assets%rowtype;\n  v_cleanup_id uuid;\nbegin\n  if p_owner_type not in (''anon'', ''customer'') then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n  if p_owner_type = ''anon'' and (p_anon_session_id is null or p_customer_id is not null) then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n  if p_owner_type = ''customer'' and (p_customer_id is null or p_anon_session_id is not null) then\n    raise exception ''user_asset_owner_invalid'' using errcode = ''22023'';\n  end if;\n\n  select asset.*\n  into v_asset\n  from public.user_assets asset\n  where asset.asset_id = p_asset_id\n  for update;\n\n  if not found then\n    raise exception ''user_asset_not_found'' using errcode = ''P0002'';\n  end if;\n\n  if v_asset.owner_type::text <> p_owner_type\n    or v_asset.anon_session_id is distinct from p_anon_session_id\n    or v_asset.customer_id is distinct from p_customer_id then\n    raise exception ''user_asset_owner_mismatch'' using errcode = ''42501'';\n  end if;\n\n  if exists (\n    select 1\n    from public.creations creation\n    where creation.voice_asset_id = p_asset_id\n    UNION ALL SELECT 1 FROM public.order_line_voice line WHERE line.voice_asset_id=p_asset_id\n  ) then\n    raise exception ''voice_asset_bound'' using errcode = ''23503'';\n  end if;\n\n  if nullif(btrim(v_asset.storage_path), '''') is not null then\n    insert into public.user_asset_cleanup_outbox (\n      asset_id,\n      asset_type,\n      bucket_name,\n      storage_path,\n      reason,\n      cleanup_status,\n      next_attempt_at,\n      updated_at\n    )\n    values (\n      v_asset.asset_id,\n      v_asset.asset_type::text,\n      ''raw-private'',\n      v_asset.storage_path,\n      ''owner_delete'',\n      ''pending'',\n      now(),\n      now()\n    )\n    on conflict (bucket_name, storage_path) do update\n    set cleanup_status = ''pending'',\n        next_attempt_at = now(),\n        updated_at = now()\n    returning public.user_asset_cleanup_outbox.cleanup_id into v_cleanup_id;\n  end if;\n\n  delete from public.user_assets asset\n  where asset.asset_id = v_asset.asset_id;\n\n  return query\n  select v_cleanup_id, ''raw-private''::text, v_asset.storage_path;\nend;\n","after_md5":"06c3c8bf256f65860b67f63646afdcf1"},{"identity":"public.enqueue_expired_unbound_voice_assets(p_cutoff timestamp with time zone, p_limit integer)","before":{"oid":"91172","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":63,"identity":"public.enqueue_expired_unbound_voice_assets(p_cutoff timestamp with time zone, p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":63,"body_bytes":1690,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"integer","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"df70beabb6c70a3c997dcce60716bd9b","definition_md5":"0e7005b37d6e29735a56aad31b5b356e","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_deleted integer := 0;\nbegin\n  if p_cutoff is null or p_limit not between 1 and 200 then\n    raise exception ''voice_cleanup_input_invalid'' using errcode = ''22023'';\n  end if;\n\n  with candidates as (\n    select asset.asset_id\n    from public.user_assets asset\n    where asset.asset_type::text = ''voice_sample''\n      and asset.created_at < p_cutoff\n      and nullif(btrim(asset.storage_path), '''') is not null\n      and not exists (\n        select 1\n        from public.creations creation\n        where creation.voice_asset_id = asset.asset_id\n        UNION ALL SELECT 1 FROM public.order_line_voice line WHERE line.voice_asset_id=asset.asset_id\n      )\n    order by asset.created_at, asset.asset_id\n    for update of asset skip locked\n    limit p_limit\n  ), queued as (\n    insert into public.user_asset_cleanup_outbox (\n      asset_id,\n      asset_type,\n      bucket_name,\n      storage_path,\n      reason,\n      cleanup_status,\n      processing_token,\n      claimed_at,\n      next_attempt_at,\n      updated_at\n    )\n    select\n      asset.asset_id,\n      asset.asset_type::text,\n      ''raw-private'',\n      asset.storage_path,\n      ''orphan_expiry'',\n      ''pending'',\n      null,\n      null,\n      now(),\n      now()\n    from public.user_assets asset\n    join candidates candidate on candidate.asset_id = asset.asset_id\n    on conflict (bucket_name, storage_path) do update\n    set cleanup_status = ''pending'',\n        processing_token = null,\n        claimed_at = null,\n        next_attempt_at = now(),\n        updated_at = now()\n    returning asset_id\n  )\n  delete from public.user_assets asset\n  using queued\n  where asset.asset_id = queued.asset_id;\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n","after_md5":"708722d3582a825658294d81ad12c9da"},{"identity":"public.enforce_signature_voice_print_triage()","before":{"oid":"91461","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":51,"identity":"public.enforce_signature_voice_print_triage()","in_scope":true,"language":"plpgsql","lf_count":51,"body_bytes":1705,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"e94cac4ceecf4318ab837e74f8aa435c","definition_md5":"deb891e35d6b5f7358edc1a06e8624d7","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_package_type text;\n  v_item_status text;\n  v_payment_id text;\n  v_item_creation_id uuid;\n  v_source_asset_id uuid;\n  v_state public.signature_voice_production_states%rowtype;\nbegin\n  if new.print_status::text <> ''released''\n    or old.print_status::text = ''released'' then\n    return new;\n  end if;\n\n  select\n    lower(coalesce(item.package_type::text, '''')),\n    item.status::text,\n    purchase_order.payment_id::text,\n    item.creation_id,\n    creation.voice_asset_id\n  into v_package_type, v_item_status, v_payment_id, v_item_creation_id, v_source_asset_id\n  from public.cart_items item\n  join public.orders purchase_order on purchase_order.order_id = item.order_id\n  left join public.order_line_voice creation on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where item.cart_item_id = new.cart_item_id\n    and item.order_id = new.order_id;\n\n  if not found or v_package_type <> ''supreme'' then\n    return new;\n  end if;\n  if v_payment_id is null\n    or v_item_status <> ''ordered''\n    or new.creation_id is null\n    or v_item_creation_id is distinct from new.creation_id\n    or v_source_asset_id is null then\n    raise exception ''Signature Voice Print Release requires an exact paid order item and bound source''\n      using errcode = ''55000'';\n  end if;\n\n  select state.* into v_state\n  from public.signature_voice_production_states state\n  where state.cart_item_id = new.cart_item_id;\n  if not found\n    or v_state.technical_status <> ''accepted''\n    or v_state.adult_declaration_status <> ''accepted'' then\n    raise exception ''Signature Voice source triage must be accepted before Print Release''\n      using errcode = ''55000'';\n  end if;\n\n  return new;\nend;\n","after_md5":"6bc3f9c1895e967451d3e0005aa4551a"},{"identity":"public.enforce_signature_voice_shipment_readiness()","before":{"oid":"91463","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":67,"identity":"public.enforce_signature_voice_shipment_readiness()","in_scope":true,"language":"plpgsql","lf_count":67,"body_bytes":2624,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"65d6a1c33bf70f5de8055255bb488a9c","definition_md5":"ba4d06fca3a8324def24fbdf0aeb2e2f","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_item record;\n  v_state public.signature_voice_production_states%rowtype;\n  v_attestation public.signature_voice_hardware_attestations%rowtype;\n  v_track_count integer;\n  v_manifest_sha256 text;\nbegin\n  if new.order_status::text not in (''shipped'', ''delivered'')\n    or old.order_status::text in (''shipped'', ''delivered'') then\n    return new;\n  end if;\n\n  for v_item in\n    select\n      item.cart_item_id,\n      item.cart_item_id, item.creation_id,\n      creation.voice_asset_id as source_asset_id\n    from public.cart_items item\n    join public.order_line_voice creation on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n    where item.order_id = new.order_id\n      and item.status::text = ''ordered''\n      and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n  loop\n    perform pg_advisory_xact_lock(hashtextextended(v_item.cart_item_id::text, 0));\n\n    if new.payment_id is null or v_item.source_asset_id is null then\n      raise exception ''Signature Voice shipment requires a paid item with a bound source''\n        using errcode = ''55000'';\n    end if;\n\n    select state.* into v_state\n    from public.signature_voice_production_states state\n    where state.cart_item_id = v_item.cart_item_id;\n    if not found\n      or v_state.technical_status <> ''accepted''\n      or v_state.adult_declaration_status <> ''accepted'' then\n      raise exception ''Signature Voice source triage is not accepted for shipment''\n        using errcode = ''55000'';\n    end if;\n\n    select manifest.out_track_count, manifest.out_manifest_sha256\n    into v_track_count, v_manifest_sha256\n    from public.signature_voice_narration_manifest(\n      v_item.cart_item_id,\n      v_item.source_asset_id\n    ) manifest;\n    if v_track_count <> 15 or v_manifest_sha256 is null then\n      raise exception ''All 15 Signature Voice narration tracks are required before shipment''\n        using errcode = ''55000'';\n    end if;\n\n    select attestation.* into v_attestation\n    from public.signature_voice_hardware_attestations attestation\n    where attestation.cart_item_id = v_item.cart_item_id;\n    if not found\n      or v_attestation.source_asset_id is distinct from v_item.source_asset_id\n      or v_attestation.narration_manifest_sha256 is distinct from v_manifest_sha256\n      or v_attestation.shipment_integrity_checked_at is null\n      or v_attestation.shipment_integrity_checked_at < clock_timestamp() - interval ''15 minutes'' then\n      raise exception ''Signature Voice hardware and narration must be verified immediately before shipment''\n        using errcode = ''55000'';\n    end if;\n  end loop;\n\n  return new;\nend;\n","after_md5":"7e8e8aeb5ad323c8060f845d249e5a8d"},{"identity":"public.commit_signature_voice_narration_track(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_slot_key text, p_source_asset_id uuid, p_expected_track_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text)","before":{"oid":"91385","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":218,"identity":"public.commit_signature_voice_narration_track(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_slot_key text, p_source_asset_id uuid, p_expected_track_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text)","in_scope":true,"language":"plpgsql","lf_count":218,"body_bytes":7123,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"d69bb915adc5a1344d5af9c74f2f267e","definition_md5":"fbb60e2b7ec466fbd590ef31d5f0e12d","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_creation public.order_line_voice%rowtype;\n  v_upload public.signature_voice_narration_uploads%rowtype;\n  v_existing public.signature_voice_narration_tracks%rowtype;\n  v_track public.signature_voice_narration_tracks%rowtype;\n  v_has_existing boolean := false;\n  v_now timestamptz := clock_timestamp();\nbegin\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text,0));\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''admin_access_required'' using errcode = ''42501'';\n  end if;\n  if p_slot_key is null\n    or p_slot_key !~ ''^narration_(0[1-9]|1[0-5])$''\n    or nullif(btrim(coalesce(p_new_storage_path, '''')), '''') is null\n    or p_new_content_type not in (\n      ''audio/webm'', ''audio/mp4'', ''audio/mpeg'', ''audio/wav'',\n      ''audio/x-wav'', ''audio/ogg'', ''audio/x-m4a''\n    )\n    or p_new_size_bytes is null\n    or p_new_size_bytes not between 1 and 15728640\n    or p_new_duration_seconds is null\n    or p_new_duration_seconds not between 1 and 600\n    or p_new_sha256 is null\n    or p_new_sha256 !~ ''^[0-9a-f]{64}$''\n    or nullif(btrim(coalesce(p_new_original_name, '''')), '''') is null\n    or char_length(p_new_original_name) > 255 then\n    raise exception ''signature_voice_narration_file_invalid'' using errcode = ''22023'';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text || '':'' || p_slot_key, 0));\n\n  select creation.*\n  into v_creation\n  from public.orders purchase_order\n  join public.cart_items item\n    on item.order_id = purchase_order.order_id\n  join public.order_line_voice creation\n    on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n    and creation.creation_id = p_creation_id\n  for update of creation;\n\n  if not found or v_creation.voice_asset_id is null then\n    raise exception ''signature_voice_order_item_not_found'' using errcode = ''P0002'';\n  end if;\n  if v_creation.voice_asset_id is distinct from p_source_asset_id then\n    raise exception ''signature_voice_source_changed'' using errcode = ''PT409'';\n  end if;\n\n  select upload.*\n  into v_upload\n  from public.signature_voice_narration_uploads upload\n  where upload.asset_id = p_new_asset_id\n  for update;\n  if not found\n    or v_upload.upload_status <> ''pending''\n    or v_upload.expires_at <= v_now\n    or v_upload.order_id is distinct from p_order_id\n    or v_upload.cart_item_id is distinct from p_cart_item_id\n    or v_upload.source_revision is distinct from v_creation.revision\n    or v_upload.creation_id is distinct from p_creation_id\n    or v_upload.slot_key is distinct from p_slot_key\n    or v_upload.source_asset_id is distinct from p_source_asset_id\n    or v_upload.expected_track_asset_id is distinct from p_expected_track_asset_id\n    or v_upload.admin_customer_id is distinct from p_admin_customer_id\n    or v_upload.storage_path is distinct from p_new_storage_path\n    or v_upload.original_filename is distinct from p_new_original_name\n    or v_upload.content_type is distinct from p_new_content_type\n    or v_upload.size_bytes is distinct from p_new_size_bytes then\n    raise exception ''signature_voice_narration_upload_invalid'' using errcode = ''23514'';\n  end if;\n\n  select track.*\n  into v_existing\n  from public.signature_voice_narration_tracks track\n  where track.cart_item_id = p_cart_item_id\n    and track.slot_key = p_slot_key\n  for update;\n  v_has_existing := found;\n\n  if (v_has_existing and v_existing.asset_id is distinct from p_expected_track_asset_id)\n    or (not v_has_existing and p_expected_track_asset_id is not null) then\n    raise exception ''signature_voice_narration_track_changed'' using errcode = ''PT409'';\n  end if;\n\n  if v_has_existing then\n    insert into public.user_asset_cleanup_outbox (\n      asset_id,\n      asset_type,\n      bucket_name,\n      storage_path,\n      reason,\n      cleanup_status,\n      processing_token,\n      claimed_at,\n      next_attempt_at,\n      updated_at\n    )\n    values (\n      v_existing.asset_id,\n      ''signature_voice_narration'',\n      ''raw-private'',\n      v_existing.storage_path,\n      ''admin_replacement'',\n      ''pending'',\n      null,\n      null,\n      v_now,\n      v_now\n    )\n    on conflict (bucket_name, storage_path) do update\n    set cleanup_status = ''pending'',\n        processing_token = null,\n        claimed_at = null,\n        next_attempt_at = v_now,\n        updated_at = v_now;\n\n    delete from public.signature_voice_narration_uploads upload\n    where upload.asset_id = v_existing.asset_id;\n  end if;\n\n  insert into public.signature_voice_narration_tracks (\n    cart_item_id, source_revision, creation_id,\n    slot_key,\n    asset_id,\n    source_asset_id,\n    storage_path,\n    original_filename,\n    content_type,\n    size_bytes,\n    duration_seconds,\n    sha256,\n    revision,\n    verified_by,\n    verified_at,\n    updated_at\n  )\n  values (\n    p_cart_item_id, v_creation.revision, p_creation_id,\n    p_slot_key,\n    p_new_asset_id,\n    p_source_asset_id,\n    p_new_storage_path,\n    p_new_original_name,\n    p_new_content_type,\n    p_new_size_bytes,\n    p_new_duration_seconds,\n    p_new_sha256,\n    1,\n    p_admin_customer_id,\n    v_now,\n    v_now\n  )\n  on conflict (cart_item_id, slot_key) do update\n  set source_revision=excluded.source_revision, asset_id = excluded.asset_id,\n      source_asset_id = excluded.source_asset_id,\n      storage_path = excluded.storage_path,\n      original_filename = excluded.original_filename,\n      content_type = excluded.content_type,\n      size_bytes = excluded.size_bytes,\n      duration_seconds = excluded.duration_seconds,\n      sha256 = excluded.sha256,\n      revision = public.signature_voice_narration_tracks.revision + 1,\n      verified_by = excluded.verified_by,\n      verified_at = excluded.verified_at,\n      updated_at = excluded.updated_at\n  returning * into v_track;\n\n  update public.signature_voice_narration_uploads upload\n  set upload_status = ''consumed'',\n      consumed_at = v_now,\n      updated_at = v_now\n  where upload.asset_id = p_new_asset_id;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    metadata\n  )\n  values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_new_asset_id,\n    p_admin_customer_id,\n    case when v_has_existing then ''narration_replaced'' else ''narration_uploaded'' end,\n    jsonb_build_object(\n      ''slot_key'', p_slot_key,\n      ''voice_source_asset_id'', p_source_asset_id,\n      ''previous_asset_id'', case when v_has_existing then v_existing.asset_id else null end,\n      ''revision'', v_track.revision,\n      ''size_bytes'', p_new_size_bytes,\n      ''duration_seconds'', p_new_duration_seconds,\n      ''sha256'', p_new_sha256\n    )\n  );\n\n  return query\n  select\n    v_track.creation_id,\n    v_track.slot_key,\n    v_track.asset_id,\n    v_track.revision,\n    v_track.verified_at;\nend;\n","after_md5":"b18f13d72d69d8d3ed3b48fb37ec1049"},{"identity":"public.set_signature_voice_source_triage(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_updated_at timestamp with time zone, p_technical_status text, p_technical_reason text, p_adult_declaration_status text, p_adult_declaration_reason text)","before":{"oid":"91293","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":176,"identity":"public.set_signature_voice_source_triage(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_updated_at timestamp with time zone, p_technical_status text, p_technical_reason text, p_adult_declaration_status text, p_adult_declaration_reason text)","in_scope":true,"language":"plpgsql","lf_count":176,"body_bytes":6475,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"8d89bccf5c0ceac1c43fb0b1e88b086b","definition_md5":"ee7c22bf0a96cd4aaf92c4340d21432a","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_creation public.order_line_voice%rowtype;\n  v_state public.signature_voice_production_states%rowtype;\n  v_existing boolean := false;\n  v_now timestamptz := clock_timestamp();\n  v_technical_reason text := nullif(btrim(coalesce(p_technical_reason, '''')), '''');\n  v_adult_reason text := nullif(btrim(coalesce(p_adult_declaration_reason, '''')), '''');\nbegin\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text,0));\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''admin_access_required'' using errcode = ''42501'';\n  end if;\n\n  if p_technical_status not in (''pending'', ''accepted'', ''rejected'')\n    or p_adult_declaration_status not in (''pending'', ''accepted'', ''rejected'') then\n    raise exception ''signature_voice_triage_status_invalid'' using errcode = ''22023'';\n  end if;\n  if p_technical_status = ''rejected'' and v_technical_reason is null then\n    raise exception ''signature_voice_technical_rejection_reason_required'' using errcode = ''22023'';\n  end if;\n  if p_adult_declaration_status = ''rejected'' and v_adult_reason is null then\n    raise exception ''signature_voice_adult_rejection_reason_required'' using errcode = ''22023'';\n  end if;\n  if coalesce(char_length(v_technical_reason), 0) > 1000\n    or coalesce(char_length(v_adult_reason), 0) > 1000 then\n    raise exception ''signature_voice_triage_reason_too_long'' using errcode = ''22023'';\n  end if;\n\n  select creation.*\n  into v_creation\n  from public.orders purchase_order\n  join public.cart_items item\n    on item.order_id = purchase_order.order_id\n  join public.order_line_voice creation\n    on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n    and creation.creation_id = p_creation_id\n    and creation.voice_asset_id is not null\n  for update of creation;\n\n  if not found then\n    raise exception ''signature_voice_order_item_not_found'' using errcode = ''P0002'';\n  end if;\n\n  select state.*\n  into v_state\n  from public.signature_voice_production_states state\n  where state.cart_item_id = p_cart_item_id\n  for update;\n  v_existing := found;\n\n  if v_existing then\n    if p_expected_updated_at is null\n      or v_state.updated_at is distinct from p_expected_updated_at then\n      raise exception ''signature_voice_triage_changed'' using errcode = ''PT409'';\n    end if;\n  elsif p_expected_updated_at is not null then\n    raise exception ''signature_voice_triage_changed'' using errcode = ''PT409'';\n  end if;\n\n  if not v_existing then\n    insert into public.signature_voice_production_states (\n      cart_item_id, creation_id,\n      source_revision\n    )\n    values (\n      p_cart_item_id, p_creation_id,\n      v_creation.revision\n    )\n    returning * into v_state;\n  end if;\n\n  if v_state.technical_status is distinct from p_technical_status\n    or v_state.technical_reason is distinct from (\n      case when p_technical_status = ''rejected'' then v_technical_reason else null end\n    ) then\n    insert into public.signature_voice_audit_events (\n      order_id,\n      cart_item_id,\n      creation_id,\n      source_asset_id,\n      actor_customer_id,\n      event_type,\n      previous_status,\n      next_status,\n      reason,\n      declared_subject_name,\n      declared_subject_relationship,\n      metadata\n    )\n    values (\n      p_order_id,\n      p_cart_item_id,\n      p_creation_id,\n      v_creation.voice_asset_id,\n      p_admin_customer_id,\n      ''technical_triage_updated'',\n      v_state.technical_status,\n      p_technical_status,\n      case when p_technical_status = ''rejected'' then v_technical_reason else null end,\n      v_creation.voice_subject_name,\n      v_creation.voice_subject_relationship,\n      jsonb_build_object(''source_revision'', v_state.source_revision)\n    );\n  end if;\n\n  if v_state.adult_declaration_status is distinct from p_adult_declaration_status\n    or v_state.adult_declaration_reason is distinct from (\n      case when p_adult_declaration_status = ''rejected'' then v_adult_reason else null end\n    ) then\n    insert into public.signature_voice_audit_events (\n      order_id,\n      cart_item_id,\n      creation_id,\n      source_asset_id,\n      actor_customer_id,\n      event_type,\n      previous_status,\n      next_status,\n      reason,\n      declared_subject_name,\n      declared_subject_relationship,\n      metadata\n    )\n    values (\n      p_order_id,\n      p_cart_item_id,\n      p_creation_id,\n      v_creation.voice_asset_id,\n      p_admin_customer_id,\n      ''adult_declaration_triage_updated'',\n      v_state.adult_declaration_status,\n      p_adult_declaration_status,\n      case when p_adult_declaration_status = ''rejected'' then v_adult_reason else null end,\n      v_creation.voice_subject_name,\n      v_creation.voice_subject_relationship,\n      jsonb_build_object(''source_revision'', v_state.source_revision)\n    );\n  end if;\n\n  update public.signature_voice_production_states state\n  set technical_status = p_technical_status,\n      technical_reason = case when p_technical_status = ''rejected'' then v_technical_reason else null end,\n      technical_reviewed_by = case when p_technical_status = ''pending'' then null else p_admin_customer_id end,\n      technical_reviewed_at = case when p_technical_status = ''pending'' then null else v_now end,\n      adult_declaration_status = p_adult_declaration_status,\n      adult_declaration_reason = case when p_adult_declaration_status = ''rejected'' then v_adult_reason else null end,\n      adult_declaration_reviewed_by = case when p_adult_declaration_status = ''pending'' then null else p_admin_customer_id end,\n      adult_declaration_reviewed_at = case when p_adult_declaration_status = ''pending'' then null else v_now end,\n      updated_at = v_now\n  where state.cart_item_id = p_cart_item_id\n  returning * into v_state;\n\n  return query\n  select\n    v_state.creation_id,\n    v_state.source_revision,\n    v_state.technical_status,\n    v_state.technical_reason,\n    v_state.technical_reviewed_by,\n    v_state.technical_reviewed_at,\n    v_state.adult_declaration_status,\n    v_state.adult_declaration_reason,\n    v_state.adult_declaration_reviewed_by,\n    v_state.adult_declaration_reviewed_at,\n    v_state.updated_at;\nend;\n","after_md5":"1198b6f7210da56acff84bbf0ed50bc2"},{"identity":"public.lock_signature_voice_narration_creation()","before":{"oid":"91457","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":22,"identity":"public.lock_signature_voice_narration_creation()","in_scope":true,"language":"plpgsql","lf_count":22,"body_bytes":781,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"889714a755eba746a2cf1e2ad632222f","definition_md5":"958522b1cf5513dbfbe3c34eb2ecdf41","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_line_id uuid;\nbegin\n  IF TG_OP=''UPDATE'' AND OLD.cart_item_id IS NULL AND NEW.cart_item_id IS NOT NULL\n    AND (to_jsonb(NEW)-''cart_item_id'')=(to_jsonb(OLD)-''cart_item_id'') THEN RETURN NEW; END IF;\n  v_line_id := case when tg_op = ''DELETE'' then old.cart_item_id else new.cart_item_id end;\n  perform pg_advisory_xact_lock(hashtextextended(v_line_id::text, 0));\n\n  if exists (\n    select 1\n    from public.cart_items item\n    join public.orders purchase_order on purchase_order.order_id = item.order_id\n    where item.cart_item_id = v_line_id\n      and item.status::text = ''ordered''\n      and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n      and purchase_order.order_status::text in (''shipped'', ''delivered'')\n  ) then\n    raise exception ''Signature Voice narration is immutable after shipment''\n      using errcode = ''55000'';\n  end if;\n\n  return case when tg_op = ''DELETE'' then old else new end;\nend;\n","after_md5":"c08a5bfb07b79e1ae9264ad0f86869e3"},{"identity":"public.invalidate_signature_voice_hardware_attestation_on_track_change()","before":{"oid":"91455","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":9,"identity":"public.invalidate_signature_voice_hardware_attestation_on_track_change()","in_scope":true,"language":"plpgsql","lf_count":9,"body_bytes":323,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"dd190f48c4af97047b078a312a7420b8","definition_md5":"056d95b024a658a8fc65c7681c3174a5","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_line_id uuid;\nbegin\n  IF TG_OP=''UPDATE'' AND OLD.cart_item_id IS NULL AND NEW.cart_item_id IS NOT NULL\n    AND (to_jsonb(NEW)-''cart_item_id'')=(to_jsonb(OLD)-''cart_item_id'') THEN RETURN NEW; END IF;\n  v_line_id := case when tg_op = ''DELETE'' then old.cart_item_id else new.cart_item_id end;\n  delete from public.signature_voice_hardware_attestations attestation\n  where attestation.cart_item_id = v_line_id;\n  UPDATE public.signature_voice_production_states state SET narration_outdated=false\n  WHERE state.cart_item_id=v_line_id\n    AND (SELECT count(*) FROM public.signature_voice_narration_tracks t\n      JOIN public.order_line_voice v ON v.cart_item_id=t.cart_item_id\n      WHERE t.cart_item_id=v_line_id AND t.source_asset_id=v.voice_asset_id AND t.source_revision=v.revision)=15;\n  return case when tg_op = ''DELETE'' then old else new end;\nend;\n","after_md5":"0717b8b817cc6557a2fb042f3e9a25ee"},{"identity":"public.invalidate_signature_voice_narration_on_source_change()","before":{"oid":"91383","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":51,"identity":"public.invalidate_signature_voice_narration_on_source_change()","in_scope":true,"language":"plpgsql","lf_count":51,"body_bytes":1918,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"e73039b04bbc1d913ec6090c9168429e","definition_md5":"5058afcaeefb00176b4c8b7aaee5b39a","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_narration_retention_until timestamptz := now() + interval ''30 days'';\nbegin\n  if old.voice_asset_id is null\n    or old.voice_asset_id is not distinct from new.voice_asset_id then\n    return new;\n  end if;\n\n  INSERT INTO public.signature_voice_production_states(cart_item_id,creation_id,source_revision,narration_outdated)\n  VALUES(NEW.cart_item_id,NEW.creation_id,NEW.revision,\n    EXISTS(SELECT 1 FROM public.signature_voice_narration_tracks WHERE cart_item_id=NEW.cart_item_id)\n    OR EXISTS(SELECT 1 FROM public.signature_voice_hardware_attestations WHERE cart_item_id=NEW.cart_item_id))\n  ON CONFLICT(cart_item_id) DO UPDATE SET source_revision=NEW.revision,\n    narration_outdated=public.signature_voice_production_states.narration_outdated OR EXCLUDED.narration_outdated,\n    technical_status=''pending'',technical_reason=NULL,technical_reviewed_by=NULL,technical_reviewed_at=NULL,\n    adult_declaration_status=''pending'',adult_declaration_reason=NULL,adult_declaration_reviewed_by=NULL,\n    adult_declaration_reviewed_at=NULL,updated_at=clock_timestamp();\n  DELETE FROM public.signature_voice_hardware_attestations WHERE cart_item_id=NEW.cart_item_id;\n  insert into public.user_asset_cleanup_outbox (\n    asset_id, asset_type, bucket_name, storage_path, reason, cleanup_status,\n    processing_token, claimed_at, next_attempt_at, updated_at\n  )\n  select\n    upload.asset_id, ''signature_voice_narration'', ''raw-private'', upload.storage_path,\n    ''admin_replacement'', ''pending'', null, null, now(), now()\n  from public.signature_voice_narration_uploads upload\n  where upload.cart_item_id = old.cart_item_id\n  on conflict (bucket_name, storage_path) do update\n  set cleanup_status = ''pending'',\n      processing_token = null,\n      claimed_at = null,\n      next_attempt_at = now(),\n      updated_at = now();\n\n  insert into public.user_asset_cleanup_outbox (\n    asset_id, asset_type, bucket_name, storage_path, reason, cleanup_status,\n    processing_token, claimed_at, next_attempt_at, updated_at\n  )\n  select\n    track.asset_id, ''signature_voice_narration'', ''raw-private'', track.storage_path,\n    ''admin_replacement'', ''pending'', null, null, v_narration_retention_until, now()\n  from public.signature_voice_narration_tracks track\n  where track.cart_item_id = old.cart_item_id\n  on conflict (bucket_name, storage_path) do update\n  set cleanup_status = ''pending'',\n      processing_token = null,\n      claimed_at = null,\n      next_attempt_at = greatest(\n        public.user_asset_cleanup_outbox.next_attempt_at,\n        excluded.next_attempt_at\n      ),\n      updated_at = now();\n\n  delete from public.signature_voice_narration_uploads upload\n  where upload.cart_item_id = old.cart_item_id;\n  delete from public.signature_voice_narration_tracks track\n  where track.cart_item_id = old.cart_item_id;\n\n  return new;\nend;\n","after_md5":"f514c1be28184b16e478d60ca8435fd0"},{"identity":"public.replace_signature_voice_source(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text, p_reason text, p_authorization_reference text, p_subject_name text, p_subject_relationship text)","before":{"oid":"91298","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":261,"identity":"public.replace_signature_voice_source(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text, p_reason text, p_authorization_reference text, p_subject_name text, p_subject_relationship text)","in_scope":true,"language":"plpgsql","lf_count":261,"body_bytes":8394,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"17271679ef83b9365cd448381d5af856","definition_md5":"569d728a09de929a4c8f290ad072a586","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\ndeclare\n  v_creation public.order_line_voice%rowtype;\n  v_old_asset public.user_assets%rowtype;\n  v_state public.signature_voice_production_states%rowtype;\n  v_upload public.signature_voice_replacement_uploads%rowtype;\n  v_now timestamptz := clock_timestamp();\n  v_reason text := nullif(btrim(coalesce(p_reason, '''')), '''');\n  v_authorization_reference text := nullif(btrim(coalesce(p_authorization_reference, '''')), '''');\n  v_subject_name text := nullif(btrim(coalesce(p_subject_name, '''')), '''');\n  v_other_binding_exists boolean := false;\n  v_authorization_id uuid;\nbegin\n  perform pg_advisory_xact_lock(hashtextextended(p_cart_item_id::text,0));\n  if not exists (\n    select 1\n    from public.customers admin_customer\n    where admin_customer.customer_id = p_admin_customer_id\n      and admin_customer.role::text = ''admin''\n  ) then\n    raise exception ''admin_access_required'' using errcode = ''42501'';\n  end if;\n  if v_reason is null or char_length(v_reason) > 1000 then\n    raise exception ''signature_voice_replacement_reason_required'' using errcode = ''22023'';\n  end if;\n  if v_authorization_reference is null or char_length(v_authorization_reference) > 500 then\n    raise exception ''signature_voice_authorization_reference_required'' using errcode = ''22023'';\n  end if;\n  if v_subject_name is null or char_length(v_subject_name) > 120\n    or p_subject_relationship not in (\n      ''self'',\n      ''parent_or_guardian'',\n      ''family_member'',\n      ''other_authorized_adult''\n    ) then\n    raise exception ''signature_voice_subject_declaration_invalid'' using errcode = ''22023'';\n  end if;\n  if nullif(btrim(coalesce(p_new_storage_path, '''')), '''') is null\n    or p_new_content_type not in (\n      ''audio/webm'',\n      ''audio/mp4'',\n      ''audio/mpeg'',\n      ''audio/wav'',\n      ''audio/x-wav'',\n      ''audio/ogg'',\n      ''audio/x-m4a''\n    )\n    or p_new_size_bytes <= 0\n    or p_new_size_bytes > 15728640\n    or p_new_duration_seconds < 10\n    or p_new_duration_seconds > 20\n    or p_new_sha256 !~ ''^[0-9a-f]{64}$'' then\n    raise exception ''signature_voice_replacement_file_invalid'' using errcode = ''22023'';\n  end if;\n\n  select creation.*\n  into v_creation\n  from public.orders purchase_order\n  join public.cart_items item\n    on item.order_id = purchase_order.order_id\n  join public.order_line_voice creation\n    on creation.cart_item_id = item.cart_item_id and creation.creation_id = item.creation_id\n  where purchase_order.order_id = p_order_id\n    and purchase_order.payment_id is not null\n    and item.cart_item_id = p_cart_item_id\n    and item.status::text = ''ordered''\n    and lower(coalesce(item.package_type::text, '''')) = ''supreme''\n    and creation.creation_id = p_creation_id\n  for update of creation;\n\n  if not found then\n    raise exception ''signature_voice_order_item_not_found'' using errcode = ''P0002'';\n  end if;\n  if v_creation.voice_asset_id is distinct from p_expected_asset_id then\n    raise exception ''signature_voice_source_changed'' using errcode = ''PT409'';\n  end if;\n\n  select upload.*\n  into v_upload\n  from public.signature_voice_replacement_uploads upload\n  where upload.asset_id = p_new_asset_id\n  for update;\n  if not found\n    or v_upload.upload_status <> ''pending''\n    or v_upload.expires_at <= v_now\n    or v_upload.order_id is distinct from p_order_id\n    or v_upload.cart_item_id is distinct from p_cart_item_id\n    or v_upload.creation_id is distinct from p_creation_id\n    or v_upload.expected_asset_id is distinct from p_expected_asset_id\n    or v_upload.source_revision is distinct from v_creation.revision\n    or v_upload.admin_customer_id is distinct from p_admin_customer_id\n    or v_upload.storage_path is distinct from p_new_storage_path\n    or v_upload.original_filename is distinct from p_new_original_name\n    or v_upload.content_type is distinct from p_new_content_type\n    or v_upload.size_bytes is distinct from p_new_size_bytes then\n    raise exception ''signature_voice_replacement_upload_invalid'' using errcode = ''23514'';\n  end if;\n\n  select asset.*\n  into v_old_asset\n  from public.user_assets asset\n  where asset.asset_id = v_creation.voice_asset_id\n  for update;\n  if not found then\n    raise exception ''signature_voice_source_not_found'' using errcode = ''P0002'';\n  end if;\n\n  insert into public.user_assets (\n    asset_id,\n    owner_type,\n    anon_session_id,\n    customer_id,\n    asset_type,\n    storage_path,\n    metadata\n  )\n  values (\n    p_new_asset_id,\n    v_creation.owner_type,\n    v_creation.anon_session_id,\n    v_creation.customer_id,\n    ''voice_sample'',\n    p_new_storage_path,\n    jsonb_build_object(\n      ''role'', ''voice'',\n      ''created_for'', ''signature_voice_replacement'',\n      ''source'', ''admin_replacement'',\n      ''original_name'', left(coalesce(p_new_original_name, ''''), 255),\n      ''content_type'', p_new_content_type,\n      ''size_bytes'', p_new_size_bytes,\n      ''duration_seconds'', p_new_duration_seconds,\n      ''sha256'', p_new_sha256,\n      ''replaced_by'', p_admin_customer_id,\n      ''replaced_at'', v_now\n    )\n  );\n\n  INSERT INTO public.order_line_voice_admin_authorizations(order_id,cart_item_id,asset_id,customer_id,\n    admin_customer_id,evidence_reference,declared_at,subject_name,subject_relationship)\n  VALUES(p_order_id,p_cart_item_id,p_new_asset_id,v_creation.customer_id,p_admin_customer_id,\n    v_authorization_reference,v_now,v_subject_name,p_subject_relationship)\n  RETURNING authorization_id INTO v_authorization_id;\n  update public.order_line_voice creation\n  set voice_asset_id = p_new_asset_id,\n      voice_sample_duration_seconds = p_new_duration_seconds,\n      voice_subject_name = v_subject_name,\n      voice_subject_relationship = p_subject_relationship,\n      binding_origin=''admin_replacement'',voice_capture_authorization_id=NULL,\n      voice_admin_authorization_id=v_authorization_id,voice_consent_version=''signature-voice-admin-declaration-v1'',\n      voice_speaker_kind=''admin_declared'',voice_consent_accepted_at=NULL,\n      voice_bound_at = v_now,\n      updated_at = v_now\n  where creation.cart_item_id = p_cart_item_id and creation.creation_id = p_creation_id RETURNING * INTO v_creation;\n\n  insert into public.signature_voice_production_states (\n    cart_item_id, creation_id,\n    source_revision,\n    technical_status,\n    adult_declaration_status,\n    updated_at\n  )\n  values (\n    p_cart_item_id, p_creation_id,\n    v_creation.revision,\n    ''pending'',\n    ''pending'',\n    v_now\n  )\n  on conflict (cart_item_id) do update\n  set source_revision = excluded.source_revision,\n      technical_status = ''pending'',\n      technical_reason = null,\n      technical_reviewed_by = null,\n      technical_reviewed_at = null,\n      adult_declaration_status = ''pending'',\n      adult_declaration_reason = null,\n      adult_declaration_reviewed_by = null,\n      adult_declaration_reviewed_at = null,\n      updated_at = v_now\n  returning * into v_state;\n\n  insert into public.signature_voice_audit_events (\n    order_id,\n    cart_item_id,\n    creation_id,\n    source_asset_id,\n    actor_customer_id,\n    event_type,\n    reason,\n    authorization_reference,\n    declared_subject_name,\n    declared_subject_relationship,\n    metadata\n  )\n  values (\n    p_order_id,\n    p_cart_item_id,\n    p_creation_id,\n    p_new_asset_id,\n    p_admin_customer_id,\n    ''source_replaced'',\n    v_reason,\n    v_authorization_reference,\n    v_subject_name,\n    p_subject_relationship,\n    jsonb_build_object(\n      ''old_asset_id'', v_old_asset.asset_id,\n      ''new_asset_id'', p_new_asset_id,\n      ''source_revision'', v_state.source_revision,\n      ''size_bytes'', p_new_size_bytes,\n      ''duration_seconds'', p_new_duration_seconds,\n      ''sha256'', p_new_sha256\n    )\n  );\n\n  update public.signature_voice_replacement_uploads upload\n  set upload_status = ''consumed'',\n      consumed_at = v_now,\n      updated_at = v_now\n  where upload.asset_id = p_new_asset_id;\n\n  select exists (\n    select 1\n    from public.creations other_creation\n    where other_creation.voice_asset_id = v_old_asset.asset_id\n    UNION ALL SELECT 1 FROM public.order_line_voice other_line WHERE other_line.voice_asset_id=v_old_asset.asset_id\n  )\n  into v_other_binding_exists;\n\n  if not v_other_binding_exists then\n    if nullif(btrim(coalesce(v_old_asset.storage_path, '''')), '''') is not null then\n      insert into public.user_asset_cleanup_outbox (\n        asset_id,\n        asset_type,\n        bucket_name,\n        storage_path,\n        reason,\n        cleanup_status,\n        next_attempt_at,\n        updated_at\n      )\n      values (\n        v_old_asset.asset_id,\n        v_old_asset.asset_type::text,\n        ''raw-private'',\n        v_old_asset.storage_path,\n        ''admin_replacement'',\n        ''pending'',\n        v_now + interval ''30 days'',\n        v_now\n      )\n      on conflict (bucket_name, storage_path) do update\n      set reason = ''admin_replacement'',\n          cleanup_status = ''pending'',\n          next_attempt_at = greatest(\n            public.user_asset_cleanup_outbox.next_attempt_at,\n            v_now + interval ''30 days''\n          ),\n          updated_at = v_now;\n    end if;\n\n    delete from public.user_assets asset\n    where asset.asset_id = v_old_asset.asset_id;\n  end if;\n\n  return query\n  select\n    p_creation_id,\n    p_new_asset_id,\n    v_old_asset.asset_id,\n    v_state.source_revision,\n    v_state.updated_at;\nend;\n","after_md5":"b9fed9faae100e60046bf11a029b18e9"},{"identity":"public.signature_voice_narration_manifest(p_creation_id uuid, p_source_asset_id uuid)","before":{"oid":"91454","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":26,"identity":"public.signature_voice_narration_manifest(p_creation_id uuid, p_source_asset_id uuid)","in_scope":true,"language":"sql","lf_count":26,"body_bytes":696,"config_md5":"41457998ccce3267dc79ae366fb8b38e","proisstrict":false,"provolatile":"s","result_type":"record","search_path":"search_path=pg_catalog, extensions","proleakproof":false,"raw_body_md5":"8041ec5e7fb3a0442e85b75727b17b0c","definition_md5":"7f1965f02d3c74a109bc58e9c37c0451","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\n  select\n    count(*)::integer,\n    case\n      when count(*) = 15 then encode(\n        extensions.digest(\n          convert_to(\n            string_agg(\n              track.slot_key || '':'' ||\n              track.asset_id::text || '':'' ||\n              track.revision::text || '':'' ||\n              track.size_bytes::text || '':'' ||\n              track.sha256,\n              E''\\n'' order by track.slot_key\n            ),\n            ''UTF8''\n          ),\n          ''sha256''\n        ),\n        ''hex''\n      )\n      else null\n    end\n  from public.signature_voice_narration_tracks track\n  where track.cart_item_id = p_cart_item_id\n    and track.source_asset_id = p_source_asset_id\n    AND track.source_revision=(SELECT revision FROM public.order_line_voice WHERE cart_item_id=p_cart_item_id);\n","after_md5":"c2e855b8de034defbd2608a6bfb0a411"},{"identity":"public.claim_user_asset_cleanup(p_limit integer)","before":{"oid":"91173","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":33,"identity":"public.claim_user_asset_cleanup(p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":33,"body_bytes":987,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"03839829cf00f15164742063ca84f31b","definition_md5":"8fa22b45c95cae7949cf9d09061209d4","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},"body":"\nDECLARE q public.user_asset_cleanup_outbox%rowtype; token uuid;\nBEGIN\n  IF p_limit NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION ''voice_cleanup_input_invalid'' USING ERRCODE=''22023''; END IF;\n  FOR q IN SELECT cleanup.* FROM public.user_asset_cleanup_outbox cleanup\n    WHERE ((cleanup.cleanup_status=''pending'' AND cleanup.next_attempt_at<=now())\n      OR (cleanup.cleanup_status=''processing'' AND cleanup.claimed_at<now()-interval ''15 minutes''))\n      AND NOT EXISTS(SELECT 1 FROM public.order_line_voice v JOIN public.user_assets a ON a.asset_id=v.voice_asset_id\n        WHERE cleanup.bucket_name=''raw-private'' AND a.storage_path=cleanup.storage_path)\n    ORDER BY cleanup.created_at,cleanup.cleanup_id FOR UPDATE SKIP LOCKED LIMIT p_limit\n  LOOP\n    -- Match the binder''s asset lock; the following statement sees committed references after waiting.\n    PERFORM 1 FROM public.user_assets a WHERE q.bucket_name=''raw-private''\n      AND (a.asset_id=q.asset_id OR a.storage_path=q.storage_path) ORDER BY a.asset_id FOR UPDATE;\n    IF q.bucket_name=''raw-private'' AND EXISTS(SELECT 1 FROM public.user_assets a\n      WHERE a.storage_path=q.storage_path AND\n        (EXISTS(SELECT 1 FROM public.order_line_voice v WHERE v.voice_asset_id=a.asset_id)\n          OR EXISTS(SELECT 1 FROM public.creations c WHERE c.voice_asset_id=a.asset_id))) THEN CONTINUE; END IF;\n    token:=gen_random_uuid();\n    UPDATE public.user_asset_cleanup_outbox SET cleanup_status=''processing'',processing_token=token,\n      claimed_at=now(),updated_at=now() WHERE cleanup_id=q.cleanup_id;\n    RETURN QUERY SELECT q.cleanup_id,q.bucket_name,q.storage_path,token;\n  END LOOP;\nEND\n","after_md5":"cc583d1f7e061a5ef21b46a4f2217578"}],"before":[{"oid":"91459","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":115,"identity":"public.attest_signature_voice_hardware_loaded(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_source_asset_id uuid, p_expected_manifest_sha256 text, p_admin_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":115,"body_bytes":3954,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"eb7e82cf5864c253830b11843b10049b","definition_md5":"137fd06fdf81357532ab98e308b0398a","security_definer":true,"execute_privi