","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"ee4bd10664540eb76e9d67ffa0e5b258","definition_md5":"265445d3b5a45680ee2d27b4c975566e","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91297","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":77,"identity":"public.record_signature_voice_source_access(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_asset_id uuid, p_admin_customer_id uuid, p_access_mode text, p_range_requested boolean)","in_scope":true,"language":"plpgsql","lf_count":77,"body_bytes":2260,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"d7cb806f234613aa5ed1198bcd54bc01","definition_md5":"7418da9f07ae17b922243f9be0b69376","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91291","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":4,"identity":"public.reject_signature_voice_audit_mutation()","in_scope":true,"language":"plpgsql","lf_count":4,"body_bytes":96,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"trigger","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"73c1baa75121c8ffdea345b52461c56e","definition_md5":"08f0b9a1614cd5b66cc247ba53ae8610","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91298","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":261,"identity":"public.replace_signature_voice_source(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_asset_id uuid, p_new_asset_id uuid, p_new_storage_path text, p_new_content_type text, p_new_size_bytes bigint, p_new_duration_seconds numeric, p_new_sha256 text, p_new_original_name text, p_reason text, p_authorization_reference text, p_subject_name text, p_subject_relationship text)","in_scope":true,"language":"plpgsql","lf_count":261,"body_bytes":8394,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"17271679ef83b9365cd448381d5af856","definition_md5":"569d728a09de929a4c8f290ad072a586","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91759","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":44,"identity":"public.reserve_signature_voice_capture_authorization(p_owner_type text, p_anon_session_id uuid, p_customer_id uuid, p_asset_id uuid, p_storage_path text, p_consent_version text, p_speaker_kind text)","in_scope":true,"language":"plpgsql","lf_count":44,"body_bytes":1601,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"3eee6f8f1765d58013d56a5fc6f9ce56","definition_md5":"98c9be778c516e20da4801ae0ff5e45d","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91293","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":176,"identity":"public.set_signature_voice_source_triage(p_order_id uuid, p_cart_item_id uuid, p_creation_id uuid, p_admin_customer_id uuid, p_expected_updated_at timestamp with time zone, p_technical_status text, p_technical_reason text, p_adult_declaration_status text, p_adult_declaration_reason text)","in_scope":true,"language":"plpgsql","lf_count":176,"body_bytes":6475,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"8d89bccf5c0ceac1c43fb0b1e88b086b","definition_md5":"ee7c22bf0a96cd4aaf92c4340d21432a","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91454","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":26,"identity":"public.signature_voice_narration_manifest(p_creation_id uuid, p_source_asset_id uuid)","in_scope":true,"language":"sql","lf_count":26,"body_bytes":696,"config_md5":"41457998ccce3267dc79ae366fb8b38e","proisstrict":false,"provolatile":"s","result_type":"record","search_path":"search_path=pg_catalog, extensions","proleakproof":false,"raw_body_md5":"8041ec5e7fb3a0442e85b75727b17b0c","definition_md5":"7f1965f02d3c74a109bc58e9c37c0451","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91173","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":33,"identity":"public.claim_user_asset_cleanup(p_limit integer)","in_scope":true,"language":"plpgsql","lf_count":33,"body_bytes":987,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"03839829cf00f15164742063ca84f31b","definition_md5":"8fa22b45c95cae7949cf9d09061209d4","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true},{"oid":"91165","owner":"postgres","prokind":"f","raw_acl":"{postgres=X/postgres,service_role=X/postgres}","cr_count":73,"identity":"public.delete_owned_unbound_user_asset(p_asset_id uuid, p_owner_type text, p_anon_session_id uuid, p_customer_id uuid)","in_scope":true,"language":"plpgsql","lf_count":73,"body_bytes":2165,"config_md5":"af3be9c3d4c2d891da1a7618c49685d3","proisstrict":false,"provolatile":"v","result_type":"record","search_path":"search_path=\"\"","proleakproof":false,"raw_body_md5":"37f9def7c2883031342142c6860d904b","definition_md5":"8f683f1c2ea7793c41eaeb33437d0218","security_definer":true,"execute_privileges":{"anon":false,"service_role":true,"authenticated":false},"has_dynamic_execute":false,"binary_reference_md5":null,"direct_voice_or_asset_reference":true}],"core":"-- Readable definitions for the generated, byte-bound S1 migration.\n-- This is Admin evidence, never a customer-clicked consent reservation.\nCREATE TABLE public.order_line_voice_admin_authorizations (\n  authorization_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id uuid NOT NULL REFERENCES public.orders(order_id) ON DELETE RESTRICT,\n  cart_item_id uuid NOT NULL REFERENCES public.cart_items(cart_item_id) ON DELETE RESTRICT,\n  asset_id uuid NOT NULL,\n  customer_id uuid NOT NULL REFERENCES public.customers(customer_id) ON DELETE RESTRICT,\n  admin_customer_id uuid NOT NULL REFERENCES public.customers(customer_id) ON DELETE RESTRICT,\n  evidence_reference text NOT NULL CHECK(length(btrim(evidence_reference)) BETWEEN 1 AND 1000),\n  declared_at timestamptz NOT NULL,\n  subject_name text NOT NULL CHECK(length(btrim(subject_name)) BETWEEN 1 AND 120),\n  subject_relationship text NOT NULL CHECK(subject_relationship IN\n    (''self'',''parent_or_guardian'',''family_member'',''other_authorized_adult'',''authorized_submitter''))\n);\n-- Historical asset UUID is evidence, like capture_authorizations.confirmed_asset_id;\n-- the CURRENT line''s asset FK protects live bytes. Evidence must survive expiry.\nALTER TABLE public.order_line_voice_admin_authorizations ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.order_line_voice_admin_authorizations FROM PUBLIC,anon,authenticated,service_role;\nGRANT SELECT ON public.order_line_voice_admin_authorizations TO service_role;\nCREATE TRIGGER order_line_voice_admin_authorizations_immutable BEFORE UPDATE OR DELETE\nON public.order_line_voice_admin_authorizations FOR EACH ROW\nEXECUTE FUNCTION public.reject_signature_voice_audit_mutation();\n\nCREATE TABLE public.order_line_voice (\n  cart_item_id uuid PRIMARY KEY REFERENCES public.cart_items(cart_item_id) ON DELETE RESTRICT,\n  order_id uuid NOT NULL REFERENCES public.orders(order_id) ON DELETE RESTRICT,\n  creation_id uuid NOT NULL REFERENCES public.creations(creation_id) ON DELETE RESTRICT,\n  owner_type public.owner_type NOT NULL DEFAULT ''customer'',\n  customer_id uuid REFERENCES public.customers(customer_id) ON DELETE RESTRICT,\n  anon_session_id uuid CHECK (anon_session_id IS NULL),\n  customize_snapshot jsonb,\n  voice_asset_id uuid REFERENCES public.user_assets(asset_id) ON DELETE RESTRICT,\n  voice_sample_duration_seconds numeric,\n  voice_consent_version text,\n  voice_consent_accepted_at timestamptz,\n  voice_bound_at timestamptz,\n  voice_subject_name text,\n  voice_subject_relationship text,\n  voice_capture_authorization_id uuid REFERENCES public.signature_voice_capture_authorizations(authorization_id) ON DELETE RESTRICT,\n  voice_admin_authorization_id uuid REFERENCES public.order_line_voice_admin_authorizations(authorization_id) ON DELETE RESTRICT,\n  voice_speaker_kind text,\n  binding_origin text NOT NULL CHECK (binding_origin IN (''inherited'',''post_payment'',''admin_replacement'')),\n  snapshot_rejected_reason text,\n  revision integer NOT NULL DEFAULT 1 CHECK (revision>0),\n  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),\n  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),\n  CONSTRAINT order_line_voice_owner_check CHECK(owner_type=''customer''),\n  CONSTRAINT order_line_voice_binding_check CHECK((\n    (voice_asset_id IS NULL AND voice_sample_duration_seconds IS NULL\n      AND voice_consent_version IS NULL AND voice_consent_accepted_at IS NULL\n      AND voice_bound_at IS NULL AND voice_subject_name IS NULL\n      AND voice_subject_relationship IS NULL AND voice_capture_authorization_id IS NULL\n      AND voice_speaker_kind IS NULL AND voice_admin_authorization_id IS NULL)\n    OR (voice_asset_id IS NOT NULL AND voice_sample_duration_seconds>0\n      AND voice_sample_duration_seconds::text NOT IN (''NaN'',''Infinity'',''-Infinity'')\n      AND voice_consent_version IN (''signature-voice-consent-v2'',''signature-voice-consent-v3'',''signature-voice-admin-declaration-v1'')\n      AND voice_bound_at IS NOT NULL AND customer_id IS NOT NULL\n      AND voice_subject_name IS NOT NULL AND voice_subject_relationship IS NOT NULL\n      AND voice_speaker_kind IS NOT NULL\n      AND ((voice_consent_version=''signature-voice-admin-declaration-v1''\n        AND voice_consent_accepted_at IS NULL AND voice_capture_authorization_id IS NULL AND voice_admin_authorization_id IS NOT NULL)\n      OR (voice_consent_version<>''signature-voice-admin-declaration-v1'' AND voice_consent_accepted_at IS NOT NULL\n        AND voice_capture_authorization_id IS NOT NULL AND voice_admin_authorization_id IS NULL)))) IS TRUE)\n);\nALTER TABLE public.order_line_voice ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON public.order_line_voice FROM PUBLIC,anon,authenticated,service_role;\nGRANT SELECT ON public.order_line_voice TO service_role;\nCREATE INDEX order_line_voice_order_idx ON public.order_line_voice(order_id);\nCREATE INDEX order_line_voice_asset_idx ON public.order_line_voice(voice_asset_id) WHERE voice_asset_id IS NOT NULL;\nCREATE INDEX order_line_voice_authorization_idx ON public.order_line_voice(voice_capture_authorization_id) WHERE voice_capture_authorization_id IS NOT NULL;\n\nCREATE FUNCTION public.guard_order_line_voice() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE i public.cart_items%rowtype; o public.orders%rowtype;\n  a public.user_assets%rowtype; v public.signature_voice_capture_authorizations%rowtype;\n  d public.order_line_voice_admin_authorizations%rowtype;\nBEGIN\n  SELECT * INTO i FROM public.cart_items WHERE cart_item_id=NEW.cart_item_id;\n  SELECT * INTO o FROM public.orders WHERE order_id=NEW.order_id;\n  IF i.order_id IS DISTINCT FROM NEW.order_id OR i.creation_id IS DISTINCT FROM NEW.creation_id\n    OR i.status::text<>''ordered'' OR i.package_type::text<>''supreme''\n    OR o.paid_at IS NULL OR o.payment_id IS NULL OR NEW.customer_id IS DISTINCT FROM o.customer_id THEN\n    RAISE EXCEPTION ''line_voice_order_mismatch'' USING ERRCODE=''23514'';\n  END IF;\n  IF TG_OP=''UPDATE'' THEN\n    IF (NEW.cart_item_id,NEW.order_id,NEW.creation_id,NEW.customize_snapshot,NEW.snapshot_rejected_reason)\n      IS DISTINCT FROM (OLD.cart_item_id,OLD.order_id,OLD.creation_id,OLD.customize_snapshot,OLD.snapshot_rejected_reason)\n      OR (NEW.customer_id IS DISTINCT FROM OLD.customer_id AND NOT\n        (OLD.customer_id IS NULL AND OLD.voice_asset_id IS NULL AND NEW.voice_asset_id IS NULL\n          AND NEW.customer_id IS NOT DISTINCT FROM o.customer_id)) THEN\n      RAISE EXCEPTION ''line_voice_identity_immutable'' USING ERRCODE=''23514'';\n    END IF;\n    IF NEW.voice_asset_id IS NOT DISTINCT FROM OLD.voice_asset_id THEN\n      IF (NEW.voice_capture_authorization_id,NEW.voice_consent_version,NEW.voice_consent_accepted_at,\n          NEW.voice_sample_duration_seconds,NEW.voice_subject_name,NEW.voice_subject_relationship,\n          NEW.voice_speaker_kind,NEW.binding_origin,NEW.voice_bound_at,NEW.revision,NEW.voice_admin_authorization_id)\n        IS DISTINCT FROM (OLD.voice_capture_authorization_id,OLD.voice_consent_version,OLD.voice_consent_accepted_at,\n          OLD.voice_sample_duration_seconds,OLD.voice_subject_name,OLD.voice_subject_relationship,\n          OLD.voice_speaker_kind,OLD.binding_origin,OLD.voice_bound_at,OLD.revision,OLD.voice_admin_authorization_id) THEN\n        RAISE EXCEPTION ''line_voice_binding_metadata_immutable'' USING ERRCODE=''23514'';\n      END IF;\n      RETURN NEW;\n    END IF;\n    IF NEW.binding_origin NOT IN (''post_payment'',''admin_replacement'') OR NEW.voice_asset_id IS NULL THEN\n      RAISE EXCEPTION ''line_voice_capture_required'' USING ERRCODE=''23514'';\n    END IF;\n    NEW.revision:=OLD.revision+1;\n    NEW.updated_at:=clock_timestamp();\n  ELSIF NEW.binding_origin<>''inherited'' OR NEW.revision<>1 THEN\n    RAISE EXCEPTION ''line_voice_initializer_required'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.voice_asset_id IS NULL THEN RETURN NEW; END IF;\n  -- Lock the source against deletion/cleanup while adding a reference.\n  SELECT * INTO a FROM public.user_assets WHERE asset_id=NEW.voice_asset_id FOR UPDATE;\n  IF EXISTS(SELECT 1 FROM public.user_asset_cleanup_outbox q WHERE q.bucket_name=''raw-private''\n    AND q.storage_path=a.storage_path AND q.cleanup_status=''processing'') THEN\n    RAISE EXCEPTION ''line_voice_cleanup_in_flight'' USING ERRCODE=''PT409'';\n  END IF;\n  IF NEW.binding_origin=''admin_replacement'' THEN\n    SELECT * INTO d FROM public.order_line_voice_admin_authorizations WHERE authorization_id=NEW.voice_admin_authorization_id;\n    IF TG_OP<>''UPDATE'' OR d.authorization_id IS NULL\n      OR d.order_id IS DISTINCT FROM NEW.order_id OR d.cart_item_id IS DISTINCT FROM NEW.cart_item_id\n      OR d.asset_id IS DISTINCT FROM NEW.voice_asset_id OR d.customer_id IS DISTINCT FROM o.customer_id\n      OR NOT public.is_admin_customer(d.admin_customer_id)\n      OR NEW.voice_consent_version<>''signature-voice-admin-declaration-v1''\n      OR NEW.voice_consent_accepted_at IS NOT NULL OR NEW.voice_capture_authorization_id IS NOT NULL\n      OR NEW.voice_speaker_kind<>''admin_declared'' OR NEW.voice_subject_name IS DISTINCT FROM d.subject_name\n      OR NEW.voice_subject_relationship IS DISTINCT FROM d.subject_relationship\n      OR NEW.voice_bound_at IS DISTINCT FROM d.declared_at\n      OR a.asset_type::text<>''voice_sample'' OR nullif(btrim(a.storage_path),'''') IS NULL\n      OR a.owner_type::text<>''customer'' OR a.customer_id IS DISTINCT FROM o.customer_id OR a.anon_session_id IS NOT NULL THEN\n      RAISE EXCEPTION ''line_voice_admin_declaration_mismatch'' USING ERRCODE=''23514'';\n    END IF;\n    RETURN NEW;\n  END IF;\n  SELECT * INTO v FROM public.signature_voice_capture_authorizations\n    WHERE authorization_id=NEW.voice_capture_authorization_id FOR KEY SHARE;\n  IF a.asset_id IS NULL OR a.asset_type::text<>''voice_sample'' OR nullif(btrim(a.storage_path),'''') IS NULL\n    OR v.authorization_id IS NULL OR v.confirmed_at IS NULL\n    OR v.confirmed_asset_id IS DISTINCT FROM NEW.voice_asset_id\n    OR v.consent_version IS DISTINCT FROM NEW.voice_consent_version\n    OR v.accepted_at IS DISTINCT FROM NEW.voice_consent_accepted_at\n    OR v.speaker_kind IS DISTINCT FROM NEW.voice_speaker_kind THEN\n    RAISE EXCEPTION ''line_voice_authorization_mismatch'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.binding_origin=''post_payment'' AND\n    (a.owner_type::text<>''customer'' OR a.customer_id IS DISTINCT FROM o.customer_id OR a.anon_session_id IS NOT NULL\n     OR v.owner_type::text<>''customer'' OR v.customer_id IS DISTINCT FROM o.customer_id OR v.anon_session_id IS NOT NULL\n     OR v.consent_version<>''signature-voice-consent-v3'') THEN\n    RAISE EXCEPTION ''line_voice_capture_owner_mismatch'' USING ERRCODE=''23514'';\n  END IF;\n  IF NEW.voice_consent_version=''signature-voice-consent-v3'' THEN\n    IF NEW.voice_speaker_kind<>''authorized_speaker'' OR NEW.voice_subject_name<>''Authorized narrator''\n      OR NEW.voice_subject_relationship<>''authorized_submitter'' THEN\n      RAISE EXCEPTION ''line_voice_v3_shape'' USING ERRCODE=''23514'';\n    END IF;\n  ELSIF NEW.voice_consent_version=''signature-voice-consent-v2'' THEN\n    IF NOT ((NEW.voice_speaker_kind=''adult'' AND NEW.voice_subject_name=''Adult narrator'' AND NEW.voice_subject_relationship=''self'')\n      OR (NEW.voice_speaker_kind=''current_child'' AND NEW.voice_subject_relationship=''parent_or_guardian''\n        AND NEW.voice_subject_name=nullif(btrim(coalesce(NEW.customize_snapshot#>>''{textOverrides,child_name}'',\n          NEW.customize_snapshot#>>''{text_overrides,child_name}'','''')),''''))) THEN\n      RAISE EXCEPTION ''line_voice_v2_shape'' USING ERRCODE=''23514'';\n    END IF;\n  ELSE RAISE EXCEPTION ''line_voice_consent_invalid'' USING ERRCODE=''23514''; END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER order_line_voice_guard BEFORE INSERT OR UPDATE ON public.order_line_voice\n  FOR EACH ROW EXECUTE FUNCTION public.guard_order_line_voice();\nREVOKE ALL ON FUNCTION public.guard_order_line_voice() FROM PUBLIC,anon,authenticated,service_role;\n\nCREATE FUNCTION public.initialize_order_line_voice(p_order uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE o public.orders%rowtype; c public.creations%rowtype; item record; reason text;\nBEGIN\n  SELECT * INTO o FROM public.orders WHERE order_id=p_order FOR UPDATE;\n  IF NOT FOUND OR o.paid_at IS NULL OR o.payment_id IS NULL THEN RETURN; END IF;\n  -- Repair only missing access identity on a previously empty snapshot, never its source.\n  UPDATE public.order_line_voice SET customer_id=o.customer_id\n    WHERE order_id=p_order AND customer_id IS NULL AND voice_asset_id IS NULL AND o.customer_id IS NOT NULL;\n  FOR item IN SELECT i.cart_item_id,i.creation_id FROM public.cart_items i\n    WHERE i.order_id=p_order AND i.status::text=''ordered'' AND i.package_type::text=''supreme''\n      AND NOT EXISTS(SELECT 1 FROM public.order_line_voice saved WHERE saved.cart_item_id=i.cart_item_id)\n  LOOP\n    SELECT * INTO c FROM public.creations WHERE creation_id=item.creation_id;\n    reason:=CASE WHEN o.customer_id IS NULL THEN ''order_customer_missing'' ELSE NULL END;\n    IF reason IS NULL THEN\n      BEGIN\n        INSERT INTO public.order_line_voice(cart_item_id,order_id,creation_id,customer_id,customize_snapshot,\n    voice_asset_id,voice_sample_duration_seconds,voice_consent_version,voice_consent_accepted_at,voice_bound_at,\n    voice_subject_name,voice_subject_relationship,voice_capture_authorization_id,voice_speaker_kind,binding_origin)\n        VALUES(item.cart_item_id,p_order,item.creation_id,o.customer_id,c.customize_snapshot,\n    c.voice_asset_id,c.voice_sample_duration_seconds,c.voice_consent_version,c.voice_consent_accepted_at,c.voice_bound_at,\n    c.voice_subject_name,c.voice_subject_relationship,c.voice_capture_authorization_id,c.voice_speaker_kind,''inherited'');\n      EXCEPTION WHEN check_violation OR foreign_key_violation OR invalid_text_representation OR numeric_value_out_of_range OR SQLSTATE ''PT409'' THEN\n        -- Only source-validation failures degrade. Structural/resource errors still surface.\n        reason:=CASE WHEN SQLSTATE=''PT409'' THEN ''source_cleanup_in_flight'' ELSE ''source_validation_failed'' END;\n      END;\n    END IF;\n    IF reason IS NOT NULL THEN\n      INSERT INTO public.order_line_voice(cart_item_id,order_id,creation_id,customer_id,customize_snapshot,binding_origin,snapshot_rejected_reason)\n      VALUES(item.cart_item_id,p_order,item.creation_id,o.customer_id,c.customize_snapshot,''inherited'',reason);\n    END IF;\n  END LOOP;\nEND $$;\nREVOKE ALL ON FUNCTION public.initialize_order_line_voice(uuid) FROM PUBLIC,anon,authenticated,service_role;\n\n-- S1 keeps customer capture first-only; S2 adds the deadline/replacement CAS contract.\nCREATE OR REPLACE FUNCTION public.materials_bind_voice(p_order uuid,p_item uuid,p_customer uuid,p_hash text,\n  p_asset uuid,p_authorization uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE c public.order_line_voice%rowtype; v public.signature_voice_capture_authorizations%rowtype; a public.user_assets%rowtype;\nBEGIN\n  PERFORM 1 FROM public.orders WHERE order_id=p_order FOR UPDATE;\n  PERFORM public.materials_assert_access(p_order,p_customer,p_hash,p_item);\n  PERFORM pg_advisory_xact_lock(hashtextextended(p_item::text,0));\n  SELECT * INTO c FROM public.order_line_voice WHERE cart_item_id=p_item AND order_id=p_order FOR UPDATE;\n  IF NOT FOUND OR c.voice_asset_id IS NOT NULL THEN RAISE EXCEPTION ''materials_voice_not_unbound''; END IF;\n  SELECT * INTO a FROM public.user_assets WHERE asset_id=p_asset FOR UPDATE;\n  SELECT * INTO v FROM public.signature_voice_capture_authorizations WHERE authorization_id=p_authorization FOR KEY SHARE;\n  IF a.asset_id IS NULL OR v.authorization_id IS NULL OR v.confirmed_asset_id IS DISTINCT FROM p_asset\n    OR v.consent_version<>''signature-voice-consent-v3'' THEN RAISE EXCEPTION ''materials_voice_authorization_invalid''; END IF;\n  UPDATE public.order_line_voice SET voice_asset_id=p_asset,voice_sample_duration_seconds=(a.metadata->>''duration_seconds'')::numeric,\n    voice_consent_version=v.consent_version,voice_consent_accepted_at=v.accepted_at,voice_bound_at=clock_timestamp(),\n    voice_subject_name=''Authorized narrator'',voice_subject_relationship=''authorized_submitter'',\n    voice_capture_authorization_id=p_authorization,voice_speaker_kind=v.speaker_kind,binding_origin=''post_payment''\n  WHERE cart_item_id=p_item AND voice_asset_id IS NULL;\nEND $$;\n\nCREATE FUNCTION public.guard_voice_line_artifact() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path='''' AS $$\nDECLARE v public.order_line_voice%rowtype; j jsonb:=to_jsonb(NEW);\nBEGIN\n  IF TG_OP=''UPDATE'' AND\n    (j->''cart_item_id'',j->''creation_id'',j->''source_asset_id'',j->''expected_asset_id'',j->''source_revision'')\n    IS NOT DISTINCT FROM\n    (to_jsonb(OLD)->''cart_item_id'',to_jsonb(OLD)->''creation_id'',to_jsonb(OLD)->''source_asset_id'',\n      to_jsonb(OLD)->''expected_asset_id'',to_jsonb(OLD)->''source_revision'') THEN RETURN NEW; END IF;\n  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cart_item_id::text,0));\n  SELECT * INTO v FROM public.order_line_voice WHERE cart_item_id=NEW.cart_item_id FOR SHARE;\n  IF NOT FOUND OR v.creation_id IS DISTINCT FROM NEW.creation_id\n    OR (j ? ''order_id'' AND (j->>''order_id'')::uuid IS DISTINCT FROM v.order_id)\n    OR (j ? ''source_revision'' AND (j->>''source_revision'')::integer IS DISTINCT FROM v.revision)\n    OR (j ? ''source_asset_id'' AND (j->>''source_asset_id'')::uuid IS DISTINCT FROM v.voice_asset_id)\n    OR (j ? ''expected_asset_id'' AND (j->>''expected_asset_id'')::uuid IS DISTINCT FROM v.voice_asset_id) THEN\n    RAISE EXCEPTION ''line_voice_artifact_mismatch'' USING ERRCODE=''PT409'';\n  END IF;\n  RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.guard_voice_line_artifact() FROM PUBLIC,anon,authenticated,service_role;\n","constraints":[{"oid":"91135","name":"creations_voice_asset_id_fkey","contype":"f","relation":"creations","definition":"FOREIGN KEY (voice_asset_id) REFERENCES user_assets(asset_id) ON DELETE RESTRICT","condeferred":false,"confdeltype":"r","confupdtype":"a","convalidated":true,"condeferrable":false,"definition_md5":"dbc02459863a6c0fdffa80d413c9b966","referenced_relation":"user_assets"},{"oid":"92279","name":"creations_voice_binding_complete_check","contype":"c","relation":"creations","definition":"CHECK (voice_asset_id IS NULL AND voice_sample_duration_seconds IS NULL AND voice_consent_version IS NULL AND voice_consent_accepted_at IS NULL AND voice_bound_at IS NULL AND voice_subject_name IS NULL AND voice_subject_relationship IS NULL OR voice_asset_id IS NOT NULL AND voice_sample_duration_seconds IS NOT NULL AND voice_sample_duration_seconds > 0::numeric AND voice_consent_version IS NOT NULL AND voice_consent_version ~ ''^signature-voice-consent-v[1-9][0-9]*$''::text AND voice_consent_accepted_at IS NOT NULL AND voice_bound_at IS NOT NULL AND voice_bound_at >= voice_consent_accepted_at AND voice_subject_name IS NOT NULL AND char_length(btrim(voice_subject_name)) >= 1 AND char_length(btrim(voice_subject_name)) <= 120 AND (voice_subject_relationship = ANY (ARRAY[''self''::text, ''parent_or_guardian''::text, ''family_member''::text, ''other_authorized_adult''::text, ''authorized_submitter''::text])))","condeferred":false,"confdeltype":" ","confupdtype":" ","convalidated":true,"condeferrable":false,"definition_md5":"71f63b877d938ed6d96ef8fcb652b458","referenced_relation":null},{"oid":"91752","name":"creations_voice_capture_authorization_id_fkey","contype":"f","relation":"creations","definition":"FOREIGN KEY (voice_capture_authorization_id) REFERENCES signature_voice_capture_authorizations(authorization_id) ON DELETE RESTRICT","condeferred":false,"confdeltype":"r","confupdtype":"a","convalidated":true,"condeferrable":false,"definition_md5":"a5621919274dc4071fa89a6941d8cedf","referenced_relation":"signature_voice_capture_authorizations"},{"oid":"91839","name":"creations_voice_capture_v2_shape_check","contype":"c","relation":"creations","definition":"CHECK (voice_consent_version = ''signature-voice-consent-v2''::text AND voice_capture_authorization_id IS NOT NULL AND (voice_speaker_kind = ANY (ARRAY[''current_child''::text, ''adult''::text])) OR voice_consent_version = ''signature-voice-consent-v3''::text AND voice_capture_authorization_id IS NOT NULL AND voice_speaker_kind = ''authorized_speaker''::text OR (voice_consent_version <> ALL (ARRAY[''signature-voice-consent-v2''::text, ''signature-voice-consent-v3''::text])) AND voice_capture_authorization_id IS NULL AND voice_speaker_kind IS NULL OR voice_consent_version IS NULL AND voice_capture_authorization_id IS NULL AND voice_speaker_kind IS NULL)","condeferred":false,"confdeltype":" ","confupdtype":" ","convalidated":true,"condeferrable":false,"definition_md5":"0a7fbc835992b73eecff0a2f36b3063b","referenced_relation":null},{"oid":"91453","name":"signature_voice_audit_event_type_v3_check","contype":"c","relation":"signature_voice_audit_events","definition":"CHECK (event_type = ANY (ARRAY[''source_accessed''::text, ''technical_triage_updated''::text, ''adult_declaration_triage_updated''::text, ''source_replaced''::text, ''narration_accessed''::text, ''narration_uploaded''::text, ''narration_replaced''::text, ''hardware_loaded_attested''::text, ''shipment_integrity_verified''::text]))","condeferred":false,"confdeltype":" ","confupdtype":" ","convalidated":true,"condeferrable":false,"definition_md5":"9a96c2434c3bd0752652f55cedc7660c","referenced_relation":null},{"oid":"91284","name":"signature_voice_audit_events_actor_customer_id_fkey","contype":"f","relation":"signature_voice_audit_events","definition":"FOREIGN KEY (actor_customer_id) REFERENCES customers(customer_id) ON DELETE RESTRICT","condeferred":false,"confdeltype":"r","confupdtype":"a","convalidated":true,"condeferrable":false,"definition_md5":"824f21b93e8c73cb1fb452e6a99dc9de","referenced_relation":"customers"},{"oid":"91261","name":"signature_voice_audit_events_authorization_reference_check","contype":"c","relation":"signature_voice_audit_events","definition":"CHECK (authorization_reference IS NULL OR char_length(authorization_reference) >= 1 AND char_length(authorization_reference) <= 500)","condeferred":false,"confdeltype":" ","confupdtype":" ","convalidated":true,"condeferrable":false,"definition_md5":"d7d191614f3a634275c3310bc596fe6a","referenced_relation":null},{"oid":"91274","name":"signature_voice_audit_events_cart_item_id_fkey","contype":"f","relation":"signature_voice_audit_events","definition":"FOREI