led":"O","function":"invalidate_signature_voice_narration_on_source_change()","internal":false,"relation":"public.creations","definition":"CREATE TRIGGER creations_signature_voice_narration_invalidation AFTER UPDATE OF voice_asset_id ON creations FOR EACH ROW EXECUTE FUNCTION invalidate_signature_voice_narration_on_source_change()","definition_md5":"92ee573a16634e2f004a1824d2b9aced"},{"name":"creations_voice_authorization_v2_guard","enabled":"O","function":"enforce_creation_voice_authorization_v2()","internal":false,"relation":"public.creations","definition":"CREATE TRIGGER creations_voice_authorization_v2_guard BEFORE INSERT OR UPDATE OF voice_asset_id, voice_consent_version, voice_capture_authorization_id, voice_speaker_kind ON creations FOR EACH ROW EXECUTE FUNCTION enforce_creation_voice_authorization_v2()","definition_md5":"25813c387d7887a94774f4dedb1f353d"},{"name":"creations_voice_binding_guard","enabled":"O","function":"enforce_creation_voice_binding()","internal":false,"relation":"public.creations","definition":"CREATE TRIGGER creations_voice_binding_guard BEFORE INSERT OR UPDATE OF voice_asset_id ON creations FOR EACH ROW EXECUTE FUNCTION enforce_creation_voice_binding()","definition_md5":"2cfcfa858ed8d5040755263d85acd3ce"},{"name":"final_jobs_signature_voice_print_triage","enabled":"O","function":"enforce_signature_voice_print_triage()","internal":false,"relation":"public.final_jobs","definition":"CREATE TRIGGER final_jobs_signature_voice_print_triage BEFORE UPDATE OF print_status, print_released_at ON final_jobs FOR EACH ROW EXECUTE FUNCTION enforce_signature_voice_print_triage()","definition_md5":"f893ff37ecf1182fffeef5c9a3745432"},{"name":"orders_materials_initialize","enabled":"O","function":"materials_initialize_paid_lines()","internal":false,"relation":"public.orders","definition":"CREATE TRIGGER orders_materials_initialize AFTER UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION materials_initialize_paid_lines()","definition_md5":"1c4dccc9d205868c32cbb