e_voice_narration_tracks FOR EACH ROW EXECUTE FUNCTION invalidate_signature_voice_hardware_attestation_on_track_change()","definition_md5":"b042b809657ed121e897218ddee8c441"}],"relations":[{"rls":true,"owner":"postgres","columns":[{"name":"event_id","type":"uuid","not_null":true},{"name":"order_id","type":"uuid","not_null":true},{"name":"cart_item_id","type":"uuid","not_null":true},{"name":"creation_id","type":"uuid","not_null":true},{"name":"source_asset_id","type":"uuid","not_null":false},{"name":"actor_customer_id","type":"uuid","not_null":true},{"name":"event_type","type":"text","not_null":true},{"name":"previous_status","type":"text","not_null":false},{"name":"next_status","type":"text","not_null":false},{"name":"reason","type":"text","not_null":false},{"name":"authorization_reference","type":"text","not_null":false},{"name":"declared_subject_name","type":"text","not_null":false},{"name":"declared_subject_relationship","type":"text","not_null":false},{"name":"metadata","type":"jsonb","not_null":true},{"name":"created_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_audit_events","force_rls":false,"view_definition_md5":null},{"rls":true,"owner":"postgres","columns":[{"name":"authorization_id","type":"uuid","not_null":true},{"name":"reserved_asset_id","type":"uuid","not_null":true},{"name":"reserved_storage_path","type":"text","not_null":true},{"name":"confirmed_asset_id","type":"uuid","not_null":false},{"name":"owner_type","type":"owner_type","not_null":true},{"name":"anon_session_id","type":"uuid","not_null":false},{"name":"customer_id","type":"uuid","not_null":false},{"name":"consent_version","type":"text","not_null":true},{"name":"speaker_kind","type":"text","not_null":true},{"name":"accepted_at","type":"timestamp with time zone","not_null":true},{"name":"confirmed_at","type":"timestamp with time zone","not_null":false},{"name":"created_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_capture_authorizations","force_rls":false,"view_definition_md5":null},{"rls":true,"owner":"postgres","columns":[{"name":"creation_id","type":"uuid","not_null":true},{"name":"source_asset_id","type":"uuid","not_null":true},{"name":"narration_manifest_sha256","type":"text","not_null":true},{"name":"attested_by","type":"uuid","not_null":true},{"name":"attested_at","type":"timestamp with time zone","not_null":true},{"name":"shipment_integrity_checked_by","type":"uuid","not_null":false},{"name":"shipment_integrity_checked_at","type":"timestamp with time zone","not_null":false},{"name":"created_at","type":"timestamp with time zone","not_null":true},{"name":"updated_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_hardware_attestations","force_rls":false,"view_definition_md5":null},{"rls":true,"owner":"postgres","columns":[{"name":"creation_id","type":"uuid","not_null":true},{"name":"slot_key","type":"text","not_null":true},{"name":"asset_id","type":"uuid","not_null":true},{"name":"source_asset_id","type":"uuid","not_null":true},{"name":"storage_path","type":"text","not_null":true},{"name":"original_filename","type":"text","not_null":true},{"name":"content_type","type":"text","not_null":true},{"name":"size_bytes","type":"bigint","not_null":true},{"name":"duration_seconds","type":"numeric","not_null":true},{"name":"sha256","type":"text","not_null":true},{"name":"revision","type":"integer","not_null":true},{"name":"verified_by","type":"uuid","not_null":true},{"name":"verified_at","type":"timestamp with time zone","not_null":true},{"name":"created_at","type":"timestamp with time zone","not_null":true},{"name":"updated_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_narration_tracks","force_rls":false,"view_definition_md5":null},{"rls":true,"owner":"postgres","columns":[{"name":"asset_id","type":"uuid","not_null":true},{"name":"order_id","type":"uuid","not_null":true},{"name":"cart_item_id","type":"uuid","not_null":true},{"name":"creation_id","type":"uuid","not_null":true},{"name":"slot_key","type":"text","not_null":true},{"name":"source_asset_id","type":"uuid","not_null":true},{"name":"expected_track_asset_id","type":"uuid","not_null":false},{"name":"admin_customer_id","type":"uuid","not_null":true},{"name":"storage_path","type":"text","not_null":true},{"name":"original_filename","type":"text","not_null":true},{"name":"content_type","type":"text","not_null":true},{"name":"size_bytes","type":"bigint","not_null":true},{"name":"upload_status","type":"text","not_null":true},{"name":"expires_at","type":"timestamp with time zone","not_null":true},{"name":"consumed_at","type":"timestamp with time zone","not_null":false},{"name":"created_at","type":"timestamp with time zone","not_null":true},{"name":"updated_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_narration_uploads","force_rls":false,"view_definition_md5":null},{"rls":true,"owner":"postgres","columns":[{"name":"creation_id","type":"uuid","not_null":true},{"name":"source_revision","type":"integer","not_null":true},{"name":"technical_status","type":"text","not_null":true},{"name":"technical_reason","type":"text","not_null":false},{"name":"technical_reviewed_by","type":"uuid","not_null":false},{"name":"technical_reviewed_at","type":"timestamp with time zone","not_null":false},{"name":"adult_declaration_status","type":"text","not_null":true},{"name":"adult_declaration_reason","type":"text","not_null":false},{"name":"adult_declaration_reviewed_by","type":"uuid","not_null":false},{"name":"adult_declaration_reviewed_at","type":"timestamp with time zone","not_null":false},{"name":"created_at","type":"timestamp with time zone","not_null":true},{"name":"updated_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_production_states","force_rls":false,"view_definition_md5":null},{"rls":true,"owner":"postgres","columns":[{"name":"asset_id","type":"uuid","not_null":true},{"name":"order_id","type":"uuid","not_null":true},{"name":"cart_item_id","type":"uuid","not_null":true},{"name":"creation_id","type":"uuid","not_null":true},{"name":"expected_asset_id","type":"uuid","not_null":true},{"name":"admin_customer_id","type":"uuid","not_null":true},{"name":"storage_path","type":"text","not_null":true},{"name":"original_filename","type":"text","not_null":true},{"name":"content_type","type":"text","not_null":true},{"name":"size_bytes","type":"bigint","not_null":true},{"name":"upload_status","type":"text","not_null":true},{"name":"expires_at","type":"timestamp with time zone","not_null":true},{"name":"consumed_at","type":"timestamp with time zone","not_null":false},{"name":"created_at","type":"timestamp with time zone","not_null":true},{"name":"updated_at","type":"timestamp with time zone","not_null":true}],"raw_acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","relkind":"r","identity":"public.signature_voice_replacement_uploads","force_rls":false,"view_definition_md5":null}]}'; r jsonb; p record; definition text; after_oid oid;
BEGIN
  PERFORM set_config('lock_timeout','5s',true);
  LOCK TABLE public.orders,public.cart_items,public.creations,public.user_assets,
    public.signature_voice_capture_authorizations,public.signature_voice_production_states,
    public.signature_voice_narration_tracks,public.signature_voice_narration_uploads,
    public.signature_voice_replacement_uploads,public.signature_voice_hardware_attestations,public.user_asset_cleanup_outbox
    IN SHARE ROW EXCLUSIVE MODE;
  IF to_regclass('public.order_line_voice') IS NOT NULL THEN RAISE EXCEPTION 'line_voice_already_installed'; END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(payload->'before') LOOP
    SELECT f.*,pg_get_userbyid(f.proowner) AS owner_name INTO p FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace
    WHERE format('%I.%I(%s)',n.nspname,f.proname,pg_get_function_identity_arguments(f.oid))=r->>'identity';
    IF p.oid IS NULL OR md5(p.prosrc) IS DISTINCT FROM r->>'raw_body_md5'
      OR p.owner_name IS DISTINCT FROM r->>'owner' OR p.proacl::text IS DISTINCT FROM r->>'raw_acl'
      OR p.prosecdef IS DISTINCT FROM (r->>'security_definer')::boolean
      OR md5(p.proconfig::text) IS DISTINCT FROM r->>'config_md5' THEN
      RAISE EXCEPTION 'line_voice_source_drift:%',r->>'identity'; END IF;
  END LOOP;

  FOR r IN SELECT * FROM jsonb_array_elements(payload->'constraints') LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid=to_regclass('public.'||(r->>'relation'))
      AND c.conname=r->>'name' AND c.convalidated=(r->>'convalidated')::boolean
      AND md5(pg_get_constraintdef(c.oid,true))=r->>'definition_md5') THEN
      RAISE EXCEPTION 'line_voice_constraint_drift:%',r->>'name'; END IF;
  END LOOP;
  FOR r IN SELECT * FROM jsonb_array_elements(payload->'triggers') LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass(r->>'relation')
      AND t.tgname=r->>'name' AND t.tgenabled::text=r->>'enabled'
      AND md5(pg_get_triggerdef(t.oid,true))=r->>'definition_md5') THEN
      RAISE EXCEPTION 'line_voice_trigger_drift:%',r->>'name'; END IF;
  END LOOP;


  FOR r IN SELECT * FROM jsonb_array_elements(payload->'relations') LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=to_regclass(r->>'identity')
      AND pg_get_userbyid(c.relowner)=r->>'owner' AND c.relacl::text IS NOT DISTINCT FROM r->>'raw_acl'
      AND c.relrowsecurity=(r->>'rls')::boolean AND c.relforcerowsecurity=(r->>'force_rls')::boolean) THEN
      RAISE EXCEPTION 'line_voice_relation_custody:%',r->>'identity'; END IF;
  END LOOP;

  -- Existing v3 consent uses authorized_submitter; permit the same value in audit metadata.
  ALTER TABLE public.signature_voice_audit_events DROP CONSTRAINT signature_voice_audit_events_declared_subject_relationshi_check;
  ALTER TABLE public.signature_voice_audit_events ADD CONSTRAINT signature_voice_audit_events_declared_subject_relationshi_check
    CHECK(declared_subject_relationship IS NULL OR declared_subject_relationship IN
      ('self','parent_or_guardian','family_member','other_authorized_adult','authorized_submitter'));
  EXECUTE payload->>'core';
ALTER TABLE public.signature_voice_production_states ADD COLUMN cart_item_id uuid REFERENCES public.order_line_voice(cart_item_id) ON DELETE RESTRICT;
ALTER TABLE public.signature_voice_narration_tracks ADD COLUMN cart_item_id uuid REFERENCES public.order_line_voice(cart_item_id) ON DELETE RESTRICT;
ALTER TABLE public.signature_voice_hardware_attestations ADD COLUMN cart_item_id uuid REFERENCES public.order_line_voice(cart_item_id) ON DELETE RESTRICT;

ALTER TABLE public.signature_voice_production_states ADD COLUMN narration_outdated boolean NOT NULL DEFAULT false;
ALTER TABLE public.signature_voice_narration_tracks ADD COLUMN source_revision integer NOT NULL DEFAULT 1;
ALTER TABLE public.signature_voice_narration_uploads ADD COLUMN source_revision integer;
ALTER TABLE public.signature_voice_replacement_uploads ADD COLUMN source_revision integer;

  FOR r IN SELECT * FROM jsonb_array_elements(payload->'patches') LOOP
    SELECT f.oid,format('%I.%I(%s)',n.nspname,f.proname,oidvectortypes(f.proargtypes)) AS signature,
      pg_get_functiondef(f.oid) AS definition,f.prosrc INTO p FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace
    WHERE format('%I.%I(%s)',n.nspname,f.proname,pg_get_function_identity_arguments(f.oid))=r->>'identity';
    definition:=replace(p.definition,p.prosrc,r->>'body');
    IF p.signature='public.signature_voice_narration_manifest(uuid, uuid)' THEN
      -- PostgreSQL requires DROP to rename an input parameter; no CASCADE or compatibility alias.
      definition:=replace(definition,'p_creation_id','p_cart_item_id');
      EXECUTE 'DROP FUNCTION '||p.signature;
    END IF;
    EXECUTE definition;
    after_oid:=to_regprocedure(p.signature);
    IF p.signature='public.signature_voice_narration_manifest(uuid, uuid)' THEN
      EXECUTE 'REVOKE ALL ON FUNCTION '||p.signature||' FROM PUBLIC,anon,authenticated,service_role';
      EXECUTE 'GRANT EXECUTE ON FUNCTION '||p.signature||' TO service_role';
    END IF;
    IF (SELECT md5(prosrc) FROM pg_proc WHERE oid=after_oid) IS DISTINCT FROM r->>'after_md5' THEN
      RAISE EXCEPTION 'line_voice_after_hash:%',r->>'identity'; END IF;
  END LOOP;

-- Exactly-one provenance backfill, never duplicate an old artifact across purchases.
PERFORM public.initialize_order_line_voice(o.order_id) FROM public.orders o
WHERE o.paid_at IS NOT NULL AND o.payment_id IS NOT NULL;

IF EXISTS(SELECT 1 FROM public.signature_voice_production_states a WHERE
  (SELECT count(*) FROM public.order_line_voice v WHERE v.creation_id=a.creation_id)<>1) THEN
  RAISE EXCEPTION 'line_voice_ambiguous_artifact:signature_voice_production_states' USING ERRCODE='23514'; END IF;
UPDATE public.signature_voice_production_states a SET cart_item_id=v.cart_item_id,source_revision=v.revision FROM public.order_line_voice v WHERE v.creation_id=a.creation_id;
ALTER TABLE public.signature_voice_production_states ALTER COLUMN cart_item_id SET NOT NULL;
ALTER TABLE public.signature_voice_production_states DROP CONSTRAINT signature_voice_production_states_pkey;
ALTER TABLE public.signature_voice_production_states ADD PRIMARY KEY(cart_item_id);

IF EXISTS(SELECT 1 FROM public.signature_voice_narration_tracks a WHERE
  (SELECT count(*) FROM public.order_line_voice v WHERE v.creation_id=a.creation_id)<>1) THEN
  RAISE EXCEPTION 'line_voice_ambiguous_artifact:signature_voice_narration_tracks' USING ERRCODE='23514'; END IF;
UPDATE public.signature_voice_narration_tracks a SET cart_item_id=v.cart_item_id FROM public.order_line_voice v WHERE v.creation_id=a.creation_id;
ALTER TABLE public.signature_voice_narration_tracks ALTER COLUMN cart_item_id SET NOT NULL;
ALTER TABLE public.signature_voice_narration_tracks DROP CONSTRAINT signature_voice_narration_tracks_pkey;
ALTER TABLE public.signature_voice_narration_tracks ADD PRIMARY KEY(cart_item_id,slot_key);

IF EXISTS(SELECT 1 FROM public.signature_voice_hardware_attestations a WHERE
  (SELECT count(*) FROM public.order_line_voice v WHERE v.creation_id=a.creation_id)<>1) THEN
  RAISE EXCEPTION 'line_voice_ambiguous_artifact:signature_voice_hardware_attestations' USING ERRCODE='23514'; END IF;
UPDATE public.signature_voice_hardware_attestations a SET cart_item_id=v.cart_item_id FROM public.order_line_voice v WHERE v.creation_id=a.creation_id;
ALTER TABLE public.signature_voice_hardware_attestations ALTER COLUMN cart_item_id SET NOT NULL;
ALTER TABLE public.signature_voice_hardware_attestations DROP CONSTRAINT signature_voice_hardware_attestations_pkey;
ALTER TABLE public.signature_voice_hardware_attestations ADD PRIMARY KEY(cart_item_id);

UPDATE public.signature_voice_narration_uploads a SET source_revision=v.revision FROM public.order_line_voice v
WHERE v.cart_item_id=a.cart_item_id AND v.creation_id=a.creation_id;
IF EXISTS(SELECT 1 FROM public.signature_voice_narration_uploads WHERE source_revision IS NULL) THEN
  RAISE EXCEPTION 'line_voice_ambiguous_upload:signature_voice_narration_uploads' USING ERRCODE='23514'; END IF;
ALTER TABLE public.signature_voice_narration_uploads ALTER COLUMN source_revision SET NOT NULL;
ALTER TABLE public.signature_voice_narration_uploads ADD CONSTRAINT signature_voice_narration_uploads_line_fk FOREIGN KEY(cart_item_id)
  REFERENCES public.order_line_voice(cart_item_id) ON DELETE RESTRICT;

UPDATE public.signature_voice_replacement_uploads a SET source_revision=v.revision FROM public.order_line_voice v
WHERE v.cart_item_id=a.cart_item_id AND v.creation_id=a.creation_id;
IF EXISTS(SELECT 1 FROM public.signature_voice_replacement_uploads WHERE source_revision IS NULL) THEN
  RAISE EXCEPTION 'line_voice_ambiguous_upload:signature_voice_replacement_uploads' USING ERRCODE='23514'; END IF;
ALTER TABLE public.signature_voice_replacement_uploads ALTER COLUMN source_revision SET NOT NULL;
ALTER TABLE public.signature_voice_replacement_uploads ADD CONSTRAINT signature_voice_replacement_uploads_line_fk FOREIGN KEY(cart_item_id)
  REFERENCES public.order_line_voice(cart_item_id) ON DELETE RESTRICT;

IF EXISTS(SELECT 1 FROM public.signature_voice_narration_tracks a JOIN public.order_line_voice v USING(cart_item_id)
  WHERE a.creation_id IS DISTINCT FROM v.creation_id OR a.source_asset_id IS DISTINCT FROM v.voice_asset_id)
  OR EXISTS(SELECT 1 FROM public.signature_voice_hardware_attestations a JOIN public.order_line_voice v USING(cart_item_id)
  WHERE a.creation_id IS DISTINCT FROM v.creation_id OR a.source_asset_id IS DISTINCT FROM v.voice_asset_id) THEN
  RAISE EXCEPTION 'line_voice_stale_artifact_source' USING ERRCODE='23514'; END IF;
DROP TRIGGER creations_signature_voice_narration_invalidation ON public.creations;
CREATE TRIGGER order_line_voice_narration_invalidation AFTER UPDATE OF voice_asset_id ON public.order_line_voice
FOR EACH ROW EXECUTE FUNCTION public.invalidate_signature_voice_narration_on_source_change();
CREATE TRIGGER voice_line_scope_guard BEFORE INSERT OR UPDATE ON public.signature_voice_production_states FOR EACH ROW EXECUTE FUNCTION public.guard_voice_line_artifact();
CREATE TRIGGER voice_line_scope_guard BEFORE INSERT OR UPDATE ON public.signature_voice_narration_tracks FOR EACH ROW EXECUTE FUNCTION public.guard_voice_line_artifact();
CREATE TRIGGER voice_line_scope_guard BEFORE INSERT OR UPDATE ON public.signature_voice_hardware_attestations FOR EACH ROW EXECUTE FUNCTION public.guard_voice_line_artifact();
CREATE TRIGGER voice_line_scope_guard BEFORE INSERT OR UPDATE ON public.signature_voice_narration_uploads FOR EACH ROW EXECUTE FUNCTION public.guard_voice_line_artifact();
CREATE TRIGGER voice_line_scope_guard BEFORE INSERT OR UPDATE ON public.signature_voice_replacement_uploads FOR EACH ROW EXECUTE FUNCTION public.guard_voice_line_artifact();


  FOR r IN SELECT * FROM jsonb_array_elements(payload->'relations') LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=to_regclass(r->>'identity')
      AND pg_get_userbyid(c.relowner)=r->>'owner' AND c.relacl::text IS NOT DISTINCT FROM r->>'raw_acl'
      AND c.relrowsecurity=(r->>'rls')::boolean AND c.relforcerowsecurity=(r->>'force_rls')::boolean) THEN
      RAISE EXCEPTION 'line_voice_relation_custody:%',r->>'identity'; END IF;
  END LOOP;

  FOR r IN SELECT * FROM jsonb_array_elements(payload->'patches') LOOP
    SELECT f.* INTO p FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace
      WHERE n.nspname='public' AND f.proname=split_part(split_part(r->>'identity','(',1),'.',2)
        AND md5(f.prosrc)=r->>'after_md5';
    IF p.oid IS NULL OR pg_get_userbyid(p.proowner) IS DISTINCT FROM r#>>'{before,owner}'
      OR p.proacl::text IS DISTINCT FROM r#>>'{before,raw_acl}'
      OR p.prosecdef IS DISTINCT FROM (r#>>'{before,security_definer}')::boolean
      OR md5(p.proconfig::text) IS DISTINCT FROM r#>>'{before,config_md5}' THEN
      RAISE EXCEPTION 'line_voice_after_custody:%',r->>'identity'; END IF;
  END LOOP;
END $line_voice$;
